contracts/AutomationSupport.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

interface AutomationToken {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
}

library AutomationTransfer {
    function invoke(address token, bytes memory data) private {
        require(token.code.length != 0, "token has no code");
        (bool ok, bytes memory result) = token.call(data);
        require(ok && (result.length == 0 || abi.decode(result, (bool))), "token transfer failed");
    }
    function transfer(address token, address to, uint256 amount) internal {
        invoke(token, abi.encodeCall(AutomationToken.transfer, (to, amount)));
    }
    function pull(address token, address from, uint256 amount) internal {
        invoke(token, abi.encodeCall(AutomationToken.transferFrom, (from, address(this), amount)));
    }
    function approve(address token, address spender, uint256 amount) internal {
        invoke(token, abi.encodeCall(AutomationToken.approve, (spender, amount)));
    }
}

/// @dev The Safe address is permanent; its signers can be rotated through the Safe itself.
abstract contract SafeAuthority {
    address public immutable safe;
    uint256 private entered;
    constructor(address safe_) {
        require(safe_ != address(0), "safe=0");
        safe = safe_;
    }
    modifier onlySafe() { require(msg.sender == safe, "not Safe"); _; }
    modifier nonReentrant() {
        require(entered == 0, "reentrant");
        entered = 1;
        _;
        entered = 0;
    }
}

interface AutomationVault {
    function notifyRewardAmount(address token, uint256 amount) external;
    function executeBuyback(uint256 amount, uint256 minimum) external;
    function buybackExecutor() external view returns (address);
}

interface AutomationDistributor {
    function depositAndDistribute(uint256 stakedAmount, uint256 bnkrAmount) external;
    function pendingSwapBnkr() external view returns (uint256);
    function swapAndNotify(uint256 minimum) external returns (uint256);
}

contracts/ConfigurationDelay.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/// @notice Fixed notice period for explicitly listed configuration setters.
/// @dev No arbitrary-call executor, bypass, or mutable delay. This is not a delay
///      on every owner action. The owner calls the original setter after waiting.
abstract contract ConfigurationDelay {
    uint256 public constant CONFIGURATION_DELAY = 48 hours;
    uint256 public constant CONFIGURATION_WINDOW = 7 days;
    mapping(bytes32 => uint256) public configurationReadyAt;

    event ConfigurationScheduled(bytes32 indexed id, bytes callData, uint256 readyAt, uint256 expiresAt);
    event ConfigurationCancelled(bytes32 indexed id);
    event ConfigurationExecuted(bytes32 indexed id);

    function _configurationOwner() internal view virtual returns (address);
    function _isDelayedConfiguration(bytes4 selector) internal pure virtual returns (bool);

    /// @notice Binds a proposal to this deployment, chain, current owner and exact calldata.
    function configurationId(bytes calldata callData) public view returns (bytes32) {
        return keccak256(abi.encode(block.chainid, address(this), _configurationOwner(), callData));
    }

    function scheduleConfiguration(bytes calldata callData) external returns (bytes32 id) {
        require(msg.sender == _configurationOwner(), "not owner");
        require(callData.length >= 4 && _isDelayedConfiguration(bytes4(callData[:4])), "unsupported configuration");
        id = configurationId(callData);
        uint256 previous = configurationReadyAt[id];
        require(previous == 0 || block.timestamp > previous + CONFIGURATION_WINDOW, "already scheduled");
        uint256 readyAt = block.timestamp + CONFIGURATION_DELAY;
        configurationReadyAt[id] = readyAt;
        emit ConfigurationScheduled(id, callData, readyAt, readyAt + CONFIGURATION_WINDOW);
    }

    function cancelConfiguration(bytes32 id) external {
        require(msg.sender == _configurationOwner(), "not owner");
        require(configurationReadyAt[id] != 0, "not scheduled");
        delete configurationReadyAt[id];
        emit ConfigurationCancelled(id);
    }

    modifier delayedConfiguration() {
        bytes32 id = configurationId(msg.data);
        uint256 readyAt = configurationReadyAt[id];
        require(readyAt != 0, "configuration not scheduled");
        require(block.timestamp >= readyAt, "configuration delay");
        require(block.timestamp <= readyAt + CONFIGURATION_WINDOW, "configuration expired");
        delete configurationReadyAt[id];
        _;
        emit ConfigurationExecuted(id);
    }
}

contracts/StakedAutomationGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
import "./AutomationSupport.sol";

interface BoundBuybackExecutor {
    function guard() external view returns (address);
    function vault() external view returns (address);
}

/// @notice Safe-approved expiring references and cumulative budgets for the existing deployments.
/// @dev These are governed limit orders, NOT a TWAP oracle. A Safe must independently validate references.
contract StakedAutomationGuard is SafeAuthority {
    struct Quote { uint128 amountIn; uint128 amountOut; }
    struct Policy {
        Quote distribution;
        Quote buybackV3;
        Quote buybackTotal;
        uint128 maxBnkrPerSwap;
        uint128 maxUsdcPerBuyback;
        uint128 bnkrBudget;
        uint128 usdcBudget;
        uint160 sqrtPriceLimitX96;
        uint48 validUntil;
        uint16 slippageBps;
    }
    address public immutable vault;
    address public immutable distributor;
    address public operator;
    address public executor;
    bool public paused = true;
    Policy public policy;
    uint256 public nonce;
    uint256 public remainingBnkr;
    uint256 public remainingUsdc;
    uint256 public constant MAX_POLICY_AGE = 1 hours;
    uint256 public constant MAX_QUOTE_BLOCKS = 2;
    uint256 public constant MAX_DEADLINE = 60 seconds;
    uint160 private constant MIN_SQRT = 4295128740;
    uint160 private constant MAX_SQRT = 1461446703485210103287273052203988822378723970341;
    bool private buying;
    uint256 private activeAmount;
    uint256 private activeMinimum;
    uint256 private activeBnkrMinimum;

    event OperatorUpdated(address indexed operator);
    event ExecutorUpdated(address indexed executor);
    event PolicyUpdated(uint256 indexed nonce, Policy policy);
    event Paused(bool paused);
    event Executed(uint256 indexed nonce, bool buyback, uint256 amountIn, uint256 minimumOut);

    constructor(address safe_, address vault_, address distributor_) SafeAuthority(safe_) {
        require(vault_.code.length > 0 && distributor_.code.length > 0, "missing contract");
        vault = vault_;
        distributor = distributor_;
    }

    function setOperator(address operator_) external onlySafe {
        operator = operator_;
        nonce++;
        emit OperatorUpdated(operator_);
    }

    function setExecutor(address executor_) external onlySafe {
        require(paused && executor_.code.length > 0, "pause first / bad executor");
        require(BoundBuybackExecutor(executor_).guard() == address(this), "wrong guard");
        require(BoundBuybackExecutor(executor_).vault() == vault, "wrong vault");
        executor = executor_;
        nonce++;
        emit ExecutorUpdated(executor_);
    }

    function setPolicy(Policy calldata p) external onlySafe {
        require(p.validUntil > block.timestamp && p.validUntil <= block.timestamp + MAX_POLICY_AGE, "bad expiry");
        require(p.slippageBps <= 100, "slippage > 1%");
        require(p.distribution.amountIn > 0 && p.distribution.amountOut > 0, "bad distribution quote");
        require(p.buybackV3.amountIn > 0 && p.buybackV3.amountOut > 0, "bad v3 quote");
        require(p.buybackTotal.amountIn > 0 && p.buybackTotal.amountOut > 0, "bad total quote");
        require(p.maxBnkrPerSwap > 0 && p.maxUsdcPerBuyback > 0, "zero cap");
        // Reject the old unrestricted extremes. Safe must choose a meaningful pool-specific limit.
        require(p.sqrtPriceLimitX96 > MIN_SQRT && p.sqrtPriceLimitX96 < MAX_SQRT, "unbounded v4 price");
        policy = p;
        remainingBnkr = p.bnkrBudget;
        remainingUsdc = p.usdcBudget;
        nonce++;
        emit PolicyUpdated(nonce, p);
    }

    function setPaused(bool value) external {
        require(msg.sender == safe || (msg.sender == operator && value), "not Safe");
        if (!value) require(policy.validUntil > block.timestamp && executor != address(0), "not configured");
        paused = value;
        nonce++;
        emit Paused(value);
    }

    function distributionFloor(uint256 amount) public view returns (uint256) { return _floor(amount, policy.distribution); }
    function buybackV3Floor(uint256 amount) public view returns (uint256) { return _floor(amount, policy.buybackV3); }
    function buybackFloor(uint256 amount) public view returns (uint256) { return _floor(amount, policy.buybackTotal); }

    function swapAndNotify(uint128 expectedAmount, uint256 minimum, uint64 quoteBlock, uint48 deadline, uint256 expectedNonce)
        external nonReentrant returns (uint256)
    {
        _check(quoteBlock, deadline, expectedNonce);
        require(expectedAmount > 0 && expectedAmount == AutomationDistributor(distributor).pendingSwapBnkr(), "batch changed");
        require(expectedAmount <= policy.maxBnkrPerSwap && expectedAmount <= remainingBnkr, "BNKR cap");
        require(minimum >= distributionFloor(expectedAmount), "below Safe floor");
        remainingBnkr -= expectedAmount;
        nonce++;
        uint256 out = AutomationDistributor(distributor).swapAndNotify(minimum);
        emit Executed(expectedNonce, false, expectedAmount, minimum);
        return out;
    }

    function executeBuyback(uint128 amount, uint256 minBnkr, uint256 minStaked, uint64 quoteBlock, uint48 deadline, uint256 expectedNonce)
        external nonReentrant
    {
        _check(quoteBlock, deadline, expectedNonce);
        require(amount > 0 && amount <= policy.maxUsdcPerBuyback && amount <= remainingUsdc, "USDC cap");
        require(minBnkr >= buybackV3Floor(amount) && minStaked >= buybackFloor(amount), "below Safe floor");
        require(executor != address(0) && AutomationVault(vault).buybackExecutor() == executor, "executor changed");
        remainingUsdc -= amount;
        nonce++;
        buying = true;
        activeAmount = amount;
        activeMinimum = minStaked;
        activeBnkrMinimum = minBnkr;
        AutomationVault(vault).executeBuyback(amount, minStaked);
        buying = false;
        delete activeAmount;
        delete activeMinimum;
        delete activeBnkrMinimum;
        emit Executed(expectedNonce, true, amount, minStaked);
    }

    /// @notice Only the bound executor, during this guard's active buyback, may retrieve execution terms.
    function buybackTerms(uint256 amount, uint256 minimum) external view returns (uint256, uint160) {
        require(buying && msg.sender == executor, "no active buyback");
        require(amount == activeAmount && minimum == activeMinimum, "terms changed");
        return (activeBnkrMinimum, policy.sqrtPriceLimitX96);
    }

    function _check(uint64 quoteBlock, uint48 deadline, uint256 expectedNonce) private view {
        require(msg.sender == operator || msg.sender == safe, "not operator");
        require(!paused && block.timestamp <= policy.validUntil, "paused or expired");
        require(expectedNonce == nonce, "stale nonce");
        require(quoteBlock <= block.number && block.number - quoteBlock <= MAX_QUOTE_BLOCKS, "stale quote block");
        require(deadline >= block.timestamp && deadline <= block.timestamp + MAX_DEADLINE, "bad deadline");
    }

    function _floor(uint256 amount, Quote memory q) private view returns (uint256) {
        require(amount > 0 && amount <= type(uint128).max && q.amountIn > 0, "bad floor input");
        // Products of two uint128 values fit uint256; round UP so dust cannot round the floor to zero.
        uint256 numerator = amount * uint256(q.amountOut);
        uint256 quoted = numerator / q.amountIn + (numerator % q.amountIn == 0 ? 0 : 1);
        require(quoted <= type(uint128).max, "quote overflow");
        uint256 adjusted = quoted * (10_000 - policy.slippageBps);
        return adjusted / 10_000 + (adjusted % 10_000 == 0 ? 0 : 1);
    }
}

contracts/StakedBoundedBuybackExecutor.s.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
import "./AutomationSupport.sol";
import {IPoolManager, ISwapRouter02} from "./StakedBuybackExecutor.sol";

interface ActiveBuybackGuard {
    function buybackTerms(uint256 amount, uint256 minimum) external view returns (uint256, uint160);
}

/// @notice Replacement executor compatible with the existing vault's two-argument buyback ABI.
/// @dev Requires an active guard call. Fixed routing, first-leg floor, bounded v4 price, no partial fills.
contract StakedBoundedBuybackExecutor is SafeAuthority {
    using AutomationTransfer for address;
    struct Config {
        address vault;
        address guard;
        address usdc;
        address weth;
        address bnkr;
        address staked;
        address router;
        address poolManager;
        uint24 feeUsdcWeth;
        uint24 feeWethBnkr;
        uint24 v4Fee;
        int24 tickSpacing;
        address hooks;
    }
    address public immutable vault;
    address public immutable guard;
    address public immutable usdc;
    address public immutable weth;
    address public immutable bnkr;
    address public immutable staked;
    address public immutable router;
    address public immutable poolManager;
    uint24 public immutable feeUsdcWeth;
    uint24 public immutable feeWethBnkr;
    bool public immutable bnkrIsCurrency0;
    IPoolManager.PoolKey public poolKey;
    bool private callbackPending;
    bytes32 private callbackHash;
    event Buyback(uint256 usdcIn, uint256 bnkrIn, uint256 stakedOut);

    constructor(address safe_, Config memory c) SafeAuthority(safe_) {
        require(c.vault.code.length > 0 && c.guard.code.length > 0, "missing vault/guard");
        require(c.router.code.length > 0 && c.poolManager.code.length > 0, "missing DEX");
        require(c.usdc.code.length > 0 && c.weth.code.length > 0 && c.bnkr.code.length > 0 && c.staked.code.length > 0, "bad tokens");
        require(c.usdc != c.bnkr && c.usdc != c.staked && c.bnkr != c.staked, "duplicate tokens");
        require(c.feeUsdcWeth > 0 && c.feeWethBnkr > 0 && c.tickSpacing > 0, "bad pool config");
        vault = c.vault;
        guard = c.guard;
        usdc = c.usdc;
        weth = c.weth;
        bnkr = c.bnkr;
        staked = c.staked;
        router = c.router;
        poolManager = c.poolManager;
        feeUsdcWeth = c.feeUsdcWeth;
        feeWethBnkr = c.feeWethBnkr;
        bool first = c.bnkr < c.staked;
        bnkrIsCurrency0 = first;
        poolKey = IPoolManager.PoolKey(first ? c.bnkr : c.staked, first ? c.staked : c.bnkr, c.v4Fee, c.tickSpacing, c.hooks);
    }

    function buyback(uint256 amount, uint256 minStaked) external nonReentrant returns (uint256 stakedOut) {
        require(msg.sender == vault && amount > 0 && minStaked > 0, "not vault / zero amount");
        (uint256 minBnkr, uint160 priceLimit) = ActiveBuybackGuard(guard).buybackTerms(amount, minStaked);
        uint256 usdcBefore = AutomationToken(usdc).balanceOf(address(this));
        uint256 bnkrBefore = AutomationToken(bnkr).balanceOf(address(this));
        uint256 stakedBefore = AutomationToken(staked).balanceOf(vault);
        usdc.pull(vault, amount);
        require(AutomationToken(usdc).balanceOf(address(this)) == usdcBefore + amount, "short USDC transfer");
        usdc.approve(router, amount);
        ISwapRouter02(router).exactInput(ISwapRouter02.ExactInputParams({
            path: abi.encodePacked(usdc, feeUsdcWeth, weth, feeWethBnkr, bnkr),
            recipient: address(this), amountIn: amount, amountOutMinimum: minBnkr
        }));
        usdc.approve(router, 0);
        require(AutomationToken(usdc).balanceOf(address(this)) == usdcBefore, "USDC not consumed");
        uint256 bnkrOut = AutomationToken(bnkr).balanceOf(address(this)) - bnkrBefore;
        require(bnkrOut >= minBnkr && bnkrOut <= uint256(uint128(type(int128).max)), "v3 output out of bounds");

        bytes memory data = abi.encode(bnkrOut, priceLimit);
        callbackHash = keccak256(data);
        callbackPending = true;
        IPoolManager(poolManager).unlock(data);
        require(!callbackPending, "missing callback");
        delete callbackHash;
        require(AutomationToken(bnkr).balanceOf(address(this)) == bnkrBefore, "BNKR not consumed");
        stakedOut = AutomationToken(staked).balanceOf(vault) - stakedBefore;
        require(stakedOut >= minStaked, "final slippage");
        emit Buyback(amount, bnkrOut, stakedOut);
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        require(msg.sender == poolManager && callbackPending && keccak256(data) == callbackHash, "unexpected callback");
        callbackPending = false; // A second callback, including nested reentry, is forbidden.
        (uint256 bnkrIn, uint160 priceLimit) = abi.decode(data, (uint256, uint160));
        int256 delta = IPoolManager(poolManager).swap(poolKey,
            IPoolManager.SwapParams(bnkrIsCurrency0, -int256(bnkrIn), priceLimit), "");
        int128 amount0 = int128(delta >> 128);
        int128 amount1 = int128(delta);
        (int128 owed, int128 received) = bnkrIsCurrency0 ? (amount0, amount1) : (amount1, amount0);
        require(owed < 0 && received > 0, "bad delta");
        // A price limit can cause a partial fill. Revert the WHOLE buyback rather than strand BNKR.
        require(uint256(-int256(owed)) == bnkrIn, "partial v4 fill");
        IPoolManager(poolManager).sync(bnkr);
        bnkr.transfer(poolManager, bnkrIn);
        require(IPoolManager(poolManager).settle() == bnkrIn, "bad settlement");
        IPoolManager(poolManager).take(staked, vault, uint256(uint128(received)));
        return abi.encode(uint256(uint128(received)));
    }

    function sweepToSafe(address token) external onlySafe nonReentrant {
        uint256 amount = AutomationToken(token).balanceOf(address(this));
        if (amount != 0) token.transfer(safe, amount);
    }
}

contracts/StakedBuybackExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/**
 * @title StakedBuybackExecutor
 * @notice Pluggable buyback executor for StakedVault. Converts forfeited USDC into $STAKED and hands it back to the
 *         caller (the vault burns it). Route: USDC -> WETH -> BNKR on Uniswap v3 (SwapRouter02 exactInput), then
 *         BNKR -> STAKED on the Uniswap v4 STAKED/BNKR pool by calling the PoolManager directly (unlock/swap/settle/take).
 *         Every hop is a real buy on the v4 pool, so each early exit becomes buy pressure on $STAKED before the burn.
 * @dev    Stateless between calls. buyback() pulls USDC from msg.sender, so it can only ever spend what the caller approved.
 *         The vault enforces minStakedOut on delivery; this contract enforces it as well so a bad route reverts here first.
 */

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface ISwapRouter02 {
    struct ExactInputParams {
        bytes path;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }
    function exactInput(ExactInputParams calldata params) external payable returns (uint256 amountOut);
}

interface IPoolManager {
    struct PoolKey {
        address currency0;
        address currency1;
        uint24 fee;
        int24 tickSpacing;
        address hooks;
    }
    struct SwapParams {
        bool zeroForOne;
        int256 amountSpecified;
        uint160 sqrtPriceLimitX96;
    }
    function unlock(bytes calldata data) external returns (bytes memory);
    function swap(PoolKey memory key, SwapParams memory params, bytes calldata hookData) external returns (int256 delta);
    function sync(address currency) external;
    function settle() external payable returns (uint256);
    function take(address currency, address to, uint256 amount) external;
}

interface IBuybackExecutor {
    function buyback(uint256 usdcAmount, uint256 minStakedOut) external returns (uint256 stakedOut);
}

contract StakedBuybackExecutor is IBuybackExecutor {
    // ---------------------------------------------------------------------
    // Immutables
    // ---------------------------------------------------------------------
    IERC20 public immutable usdc;
    IERC20 public immutable weth;
    IERC20 public immutable bnkr;
    IERC20 public immutable staked;
    ISwapRouter02 public immutable router;
    IPoolManager public immutable poolManager;

    /// @dev v4 pool key for STAKED/BNKR. currency0 = BNKR, currency1 = STAKED (sorted by address).
    IPoolManager.PoolKey public poolKey;
    bool public immutable bnkrIsCurrency0;

    // v3 fee tiers for the USDC -> WETH -> BNKR leg. Owner-tunable if liquidity migrates.
    uint24 public feeUsdcWeth;
    uint24 public feeWethBnkr;

    address public owner;
    address public pendingOwner;

    // v4 price limits (TickMath.MIN_SQRT_PRICE + 1 / MAX_SQRT_PRICE - 1)
    uint160 internal constant MIN_SQRT_PRICE_LIMIT = 4295128740;
    uint160 internal constant MAX_SQRT_PRICE_LIMIT = 1461446703485210103287273052203988822378723970341;

    uint256 public totalUsdcIn;
    uint256 public totalStakedOut;

    event Buyback(address indexed caller, uint256 usdcIn, uint256 bnkrMid, uint256 stakedOut);
    event FeesUpdated(uint24 feeUsdcWeth, uint24 feeWethBnkr);
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    error NotOwner();
    error NotPoolManager();
    error ZeroAmount();
    error Slippage(uint256 got, uint256 want);
    error TransferFailed();
    error Reentrancy();

    uint256 private _locked;
    modifier nonReentrant() {
        if (_locked == 2) revert Reentrancy();
        _locked = 2;
        _;
        _locked = 0;
    }
    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    constructor(
        address _usdc,
        address _weth,
        address _bnkr,
        address _staked,
        address _router,
        address _poolManager,
        uint24 _v4Fee,
        int24 _v4TickSpacing,
        address _v4Hooks,
        uint24 _feeUsdcWeth,
        uint24 _feeWethBnkr,
        address _owner
    ) {
        require(_usdc != address(0) && _weth != address(0) && _bnkr != address(0) && _staked != address(0), "zero token");
        require(_router != address(0) && _poolManager != address(0) && _owner != address(0), "zero addr");
        usdc = IERC20(_usdc);
        weth = IERC20(_weth);
        bnkr = IERC20(_bnkr);
        staked = IERC20(_staked);
        router = ISwapRouter02(_router);
        poolManager = IPoolManager(_poolManager);

        bool bnkrFirst = _bnkr < _staked;
        bnkrIsCurrency0 = bnkrFirst;
        poolKey = IPoolManager.PoolKey({
            currency0: bnkrFirst ? _bnkr : _staked,
            currency1: bnkrFirst ? _staked : _bnkr,
            fee: _v4Fee,
            tickSpacing: _v4TickSpacing,
            hooks: _v4Hooks
        });
        feeUsdcWeth = _feeUsdcWeth;
        feeWethBnkr = _feeWethBnkr;
        owner = _owner;
        emit OwnershipTransferred(address(0), _owner);
    }

    // ---------------------------------------------------------------------
    // Buyback
    // ---------------------------------------------------------------------

    /// @inheritdoc IBuybackExecutor
    function buyback(uint256 usdcAmount, uint256 minStakedOut) external nonReentrant returns (uint256 stakedOut) {
        if (usdcAmount == 0) revert ZeroAmount();

        // 1. pull USDC from caller (vault approves exactly usdcAmount before calling)
        _safeTransferFrom(usdc, msg.sender, address(this), usdcAmount);

        // 2. USDC -> WETH -> BNKR on v3
        _safeApprove(usdc, address(router), usdcAmount);
        uint256 bnkrBefore = bnkr.balanceOf(address(this));
        router.exactInput(
            ISwapRouter02.ExactInputParams({
                path: abi.encodePacked(address(usdc), feeUsdcWeth, address(weth), feeWethBnkr, address(bnkr)),
                recipient: address(this),
                amountIn: usdcAmount,
                amountOutMinimum: 0 // final slippage check is on STAKED delivered
            })
        );
        _safeApprove(usdc, address(router), 0);
        uint256 bnkrOut = bnkr.balanceOf(address(this)) - bnkrBefore;
        if (bnkrOut == 0) revert ZeroAmount();

        // 3. BNKR -> STAKED on the v4 pool, delivered straight to the caller
        bytes memory result = poolManager.unlock(abi.encode(bnkrOut, msg.sender));
        stakedOut = abi.decode(result, (uint256));
        if (stakedOut < minStakedOut) revert Slippage(stakedOut, minStakedOut);

        totalUsdcIn += usdcAmount;
        totalStakedOut += stakedOut;
        emit Buyback(msg.sender, usdcAmount, bnkrOut, stakedOut);
    }

    /// @dev Called by the PoolManager inside unlock(). Performs the swap and settles both sides.
    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        (uint256 bnkrIn, address recipient) = abi.decode(data, (uint256, address));

        bool zeroForOne = bnkrIsCurrency0; // selling BNKR for STAKED
        int256 delta = poolManager.swap(
            poolKey,
            IPoolManager.SwapParams({
                zeroForOne: zeroForOne,
                amountSpecified: -int256(bnkrIn), // exact input (negative in v4)
                sqrtPriceLimitX96: zeroForOne ? MIN_SQRT_PRICE_LIMIT : MAX_SQRT_PRICE_LIMIT
            }),
            ""
        );

        // BalanceDelta packs amount0 in the upper 128 bits and amount1 in the lower 128 bits.
        int128 amount0 = int128(delta >> 128);
        int128 amount1 = int128(delta);
        (int128 owed, int128 received) = zeroForOne ? (amount0, amount1) : (amount1, amount0);
        require(owed < 0 && received > 0, "bad delta");

        // pay BNKR in: sync -> transfer -> settle
        address bnkrCurrency = address(bnkr);
        poolManager.sync(bnkrCurrency);
        _safeTransfer(bnkr, address(poolManager), uint256(uint128(-owed)));
        poolManager.settle();

        // take STAKED out directly to the recipient (the vault)
        uint256 out = uint256(uint128(received));
        poolManager.take(address(staked), recipient, out);

        return abi.encode(out);
    }

    // ---------------------------------------------------------------------
    // Admin
    // ---------------------------------------------------------------------
    function setV3Fees(uint24 _feeUsdcWeth, uint24 _feeWethBnkr) external onlyOwner {
        feeUsdcWeth = _feeUsdcWeth;
        feeWethBnkr = _feeWethBnkr;
        emit FeesUpdated(_feeUsdcWeth, _feeWethBnkr);
    }

    /// @notice Nothing should ever sit here between calls; lets the owner sweep dust or mistaken sends.
    function rescueToken(address token, address to, uint256 amount) external onlyOwner {
        _safeTransfer(IERC20(token), to, amount);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    function acceptOwnership() external {
        require(msg.sender == pendingOwner, "not pending");
        emit OwnershipTransferred(owner, msg.sender);
        owner = msg.sender;
        pendingOwner = address(0);
    }

    // ---------------------------------------------------------------------
    // Internal safe-ERC20 helpers (USDC on Base returns bool; STAKED/BNKR are standard)
    // ---------------------------------------------------------------------
    function _safeTransfer(IERC20 token, address to, uint256 amount) internal {
        (bool ok, bytes memory ret) = address(token).call(abi.encodeWithSelector(token.transfer.selector, to, amount));
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool)))) revert TransferFailed();
    }

    function _safeTransferFrom(IERC20 token, address from, address to, uint256 amount) internal {
        (bool ok, bytes memory ret) =
            address(token).call(abi.encodeWithSelector(token.transferFrom.selector, from, to, amount));
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool)))) revert TransferFailed();
    }

    function _safeApprove(IERC20 token, address spender, uint256 amount) internal {
        (bool ok, bytes memory ret) = address(token).call(abi.encodeWithSelector(token.approve.selector, spender, amount));
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool)))) revert TransferFailed();
    }
}

contracts/StakedDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/**
 * @title StakedDistributor (v2)
 * @notice Automated fee router for $STAKED trading fees (paid in $STAKED and $BNKR).
 *
 *  $STAKED fees  : 50% burned to 0xdead, 50% to `liquidityWallet` (liquidity deepening)
 *  $BNKR fees    : 50% to `bnkrStakingWallet` (staked in Bankr; yield is fed back to the vault as BNKR rewards)
 *                  50% parked in `pendingSwapBnkr` until it reaches `minBnkrBatch`, then swapped to USDC
 *                  BNKR -> WETH -> USDC on Uniswap V3 (SwapRouter02) and streamed to StakedVault.
 *
 *  `distribute()` (the 50/50 splits) is permissionless. `swapAndNotify(minUsdcOut)` is keeper-gated and requires
 *  a caller-supplied minimum output so a permissionless poke can never be sandwiched.
 *  `pendingSwapBnkr` is accounted separately, so a failed / delayed swap never lets the staking wallet's share
 *  be split a second time.
 */

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

/// @dev Uniswap V3 SwapRouter02 (Base: 0x2626664c2603336E57B271c5C0b26F421741e481) — exactInput has no deadline field.
interface ISwapRouter02 {
    struct ExactInputParams {
        bytes path;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }

    function exactInput(ExactInputParams calldata params) external payable returns (uint256 amountOut);
}

interface IStakedVault {
    function notifyRewardAmount(address token, uint256 amount) external;
}

library SafeERC20Lite {
    function safeTransfer(IERC20 token, address to, uint256 amount) internal {
        _call(address(token), abi.encodeWithSelector(token.transfer.selector, to, amount));
    }

    function safeTransferFrom(IERC20 token, address from, address to, uint256 amount) internal {
        _call(address(token), abi.encodeWithSelector(token.transferFrom.selector, from, to, amount));
    }

    function safeApprove(IERC20 token, address spender, uint256 amount) internal {
        _call(address(token), abi.encodeWithSelector(token.approve.selector, spender, amount));
    }

    function _call(address token, bytes memory data) private {
        (bool ok, bytes memory ret) = token.call(data);
        require(ok && (ret.length == 0 || abi.decode(ret, (bool))), "SafeERC20: operation failed");
    }
}

abstract contract Ownable2Step {
    address public owner;
    address public pendingOwner;

    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor(address initialOwner) {
        require(initialOwner != address(0), "owner=0");
        owner = initialOwner;
        emit OwnershipTransferred(address(0), initialOwner);
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    function acceptOwnership() external {
        require(msg.sender == pendingOwner, "not pending owner");
        emit OwnershipTransferred(owner, pendingOwner);
        owner = pendingOwner;
        pendingOwner = address(0);
    }
}

abstract contract ReentrancyGuard {
    uint256 private _status = 1;

    modifier nonReentrant() {
        require(_status == 1, "reentrant");
        _status = 2;
        _;
        _status = 1;
    }
}

contract StakedDistributor is Ownable2Step, ReentrancyGuard {
    using SafeERC20Lite for IERC20;

    IERC20 public immutable stakedToken;
    IERC20 public immutable bnkr;
    IERC20 public immutable usdc;
    address public immutable weth;

    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    uint256 public constant BPS = 10_000;
    uint256 public constant STAKED_BURN_BPS = 5000; // 50% of STAKED fees burned
    uint256 public constant BNKR_STAKING_BPS = 5000; // 50% of BNKR fees to Bankr staking

    ISwapRouter02 public swapRouter;
    IStakedVault public vault;
    address public liquidityWallet;
    address public bnkrStakingWallet;
    address public keeper;

    uint256 public minBnkrBatch; // BNKR-wei threshold (~$100 worth; owner-adjustable as price moves)
    uint256 public pendingSwapBnkr; // BNKR accumulated for the USDC leg, not yet swapped
    uint24 public bnkrWethFee = 10_000; // BNKR/WETH v3 pool fee tier (1%)
    uint24 public wethUsdcFee = 500; // WETH/USDC v3 pool fee tier (0.05%)

    // Lifetime stats
    uint256 public totalStakedBurned;
    uint256 public totalStakedToLiquidity;
    uint256 public totalBnkrToStaking;
    uint256 public totalBnkrSwapped;
    uint256 public totalUsdcToVault;

    event StakedDistributed(uint256 burned, uint256 toLiquidity);
    event BnkrDistributed(uint256 toStaking, uint256 queuedForSwap, uint256 pendingSwapTotal);
    event SwappedAndNotified(uint256 bnkrIn, uint256 usdcOut);
    event MinBnkrBatchUpdated(uint256 threshold);
    event PoolFeesUpdated(uint24 bnkrWethFee, uint24 wethUsdcFee);
    event VaultUpdated(address vault);
    event RouterUpdated(address router);
    event LiquidityWalletUpdated(address wallet);
    event BnkrStakingWalletUpdated(address wallet);
    event KeeperUpdated(address keeper);
    event Rescued(address token, uint256 amount, address to);

    constructor(
        address _stakedToken,
        address _bnkr,
        address _usdc,
        address _weth,
        address _swapRouter,
        address _vault,
        address _owner,
        uint256 _minBnkrBatch
    ) Ownable2Step(_owner) {
        require(
            _stakedToken != address(0) && _bnkr != address(0) && _usdc != address(0) && _weth != address(0)
                && _swapRouter != address(0) && _vault != address(0),
            "zero address"
        );
        stakedToken = IERC20(_stakedToken);
        bnkr = IERC20(_bnkr);
        usdc = IERC20(_usdc);
        weth = _weth;
        swapRouter = ISwapRouter02(_swapRouter);
        vault = IStakedVault(_vault);
        liquidityWallet = _owner;
        bnkrStakingWallet = _owner;
        keeper = _owner;
        minBnkrBatch = _minBnkrBatch;
    }

    modifier onlyKeeperOrOwner() {
        require(msg.sender == keeper || msg.sender == owner, "not keeper");
        _;
    }

    // ---------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------
    function undistributedStaked() public view returns (uint256) {
        return stakedToken.balanceOf(address(this));
    }

    function undistributedBnkr() public view returns (uint256) {
        uint256 bal = bnkr.balanceOf(address(this));
        return bal > pendingSwapBnkr ? bal - pendingSwapBnkr : 0;
    }

    function canSwap() external view returns (bool) {
        return pendingSwapBnkr >= minBnkrBatch && pendingSwapBnkr > 0;
    }

    function swapPath() public view returns (bytes memory) {
        return abi.encodePacked(address(bnkr), bnkrWethFee, weth, wethUsdcFee, address(usdc));
    }

    // ---------------------------------------------------------------------
    // Distribution
    // ---------------------------------------------------------------------
    /// @notice Pull fees from the caller (after approval) and distribute in one tx. Handy for the owner automation.
    function depositAndDistribute(uint256 stakedAmount, uint256 bnkrAmount) external nonReentrant {
        if (stakedAmount > 0) stakedToken.safeTransferFrom(msg.sender, address(this), stakedAmount);
        if (bnkrAmount > 0) bnkr.safeTransferFrom(msg.sender, address(this), bnkrAmount);
        _distributeStaked();
        _distributeBnkr();
    }

    /// @notice Split whatever is sitting in the contract. Permissionless — no swap happens here.
    function distribute() external nonReentrant {
        _distributeStaked();
        _distributeBnkr();
    }

    function _distributeStaked() internal {
        uint256 bal = stakedToken.balanceOf(address(this));
        if (bal == 0) return;
        uint256 burn = (bal * STAKED_BURN_BPS) / BPS;
        uint256 liq = bal - burn;
        totalStakedBurned += burn;
        totalStakedToLiquidity += liq;
        if (burn > 0) stakedToken.safeTransfer(DEAD, burn);
        if (liq > 0) stakedToken.safeTransfer(liquidityWallet, liq);
        emit StakedDistributed(burn, liq);
    }

    function _distributeBnkr() internal {
        uint256 avail = undistributedBnkr();
        if (avail == 0) return;
        uint256 toStaking = (avail * BNKR_STAKING_BPS) / BPS;
        uint256 toSwap = avail - toStaking;
        totalBnkrToStaking += toStaking;
        pendingSwapBnkr += toSwap;
        if (toStaking > 0) bnkr.safeTransfer(bnkrStakingWallet, toStaking);
        emit BnkrDistributed(toStaking, toSwap, pendingSwapBnkr);
    }

    /// @notice Swap the queued BNKR batch to USDC and stream it into the vault.
    /// @param minUsdcOut Minimum USDC out — keeper derives this off-chain from a fresh quote (slippage guard).
    function swapAndNotify(uint256 minUsdcOut) external nonReentrant onlyKeeperOrOwner returns (uint256 usdcOut) {
        uint256 amountIn = pendingSwapBnkr;
        require(amountIn > 0 && amountIn >= minBnkrBatch, "below batch threshold");
        require(minUsdcOut > 0, "minOut=0");
        pendingSwapBnkr = 0;

        bnkr.safeApprove(address(swapRouter), amountIn);
        usdcOut = swapRouter.exactInput(
            ISwapRouter02.ExactInputParams({
                path: swapPath(),
                recipient: address(this),
                amountIn: amountIn,
                amountOutMinimum: minUsdcOut
            })
        );
        bnkr.safeApprove(address(swapRouter), 0);
        require(usdcOut >= minUsdcOut, "slippage");

        totalBnkrSwapped += amountIn;
        totalUsdcToVault += usdcOut;

        usdc.safeApprove(address(vault), usdcOut);
        vault.notifyRewardAmount(address(usdc), usdcOut);
        usdc.safeApprove(address(vault), 0);

        emit SwappedAndNotified(amountIn, usdcOut);
    }

    // ---------------------------------------------------------------------
    // Admin
    // ---------------------------------------------------------------------
    function setMinBnkrBatch(uint256 _threshold) external onlyOwner {
        minBnkrBatch = _threshold;
        emit MinBnkrBatchUpdated(_threshold);
    }

    function setPoolFees(uint24 _bnkrWethFee, uint24 _wethUsdcFee) external onlyOwner {
        bnkrWethFee = _bnkrWethFee;
        wethUsdcFee = _wethUsdcFee;
        emit PoolFeesUpdated(_bnkrWethFee, _wethUsdcFee);
    }

    function setVault(address _vault) external onlyOwner {
        require(_vault != address(0), "vault=0");
        vault = IStakedVault(_vault);
        emit VaultUpdated(_vault);
    }

    function setSwapRouter(address _router) external onlyOwner {
        require(_router != address(0), "router=0");
        swapRouter = ISwapRouter02(_router);
        emit RouterUpdated(_router);
    }

    function setLiquidityWallet(address _wallet) external onlyOwner {
        require(_wallet != address(0), "wallet=0");
        liquidityWallet = _wallet;
        emit LiquidityWalletUpdated(_wallet);
    }

    function setBnkrStakingWallet(address _wallet) external onlyOwner {
        require(_wallet != address(0), "wallet=0");
        bnkrStakingWallet = _wallet;
        emit BnkrStakingWalletUpdated(_wallet);
    }

    function setKeeper(address _keeper) external onlyOwner {
        keeper = _keeper;
        emit KeeperUpdated(_keeper);
    }

    /// @notice Rescue stray tokens. $STAKED can never be rescued (it is always burn/liquidity-bound), and BNKR
    ///         queued for the stakers' USDC leg (`pendingSwapBnkr`) is protected.
    function rescueToken(address token, uint256 amount, address to) external onlyOwner {
        require(token != address(stakedToken), "STAKED protected");
        if (token == address(bnkr)) require(amount <= undistributedBnkr(), "pending swap protected");
        IERC20(token).safeTransfer(to, amount);
        emit Rescued(token, amount, to);
    }
}

