// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity 0.8.24;
// Port of Uniswap/v3-core v1.0.0 TickMath.getSqrtRatioAtTick; unused inverse omitted.

/// @title Math library for computing sqrt prices from ticks and vice versa
/// @notice Computes sqrt price for ticks of size 1.0001, i.e. sqrt(1.0001^tick) as fixed point Q64.96 numbers. Supports
/// prices between 2**-128 and 2**128
library StakedTickMath {
    /// @dev The minimum tick that may be passed to #getSqrtRatioAtTick computed from log base 1.0001 of 2**-128
    int24 internal constant MIN_TICK = -887272;
    /// @dev The maximum tick that may be passed to #getSqrtRatioAtTick computed from log base 1.0001 of 2**128
    int24 internal constant MAX_TICK = -MIN_TICK;

    /// @dev The minimum value that can be returned from #getSqrtRatioAtTick. Equivalent to getSqrtRatioAtTick(MIN_TICK)
    uint160 internal constant MIN_SQRT_RATIO = 4295128739;
    /// @dev The maximum value that can be returned from #getSqrtRatioAtTick. Equivalent to getSqrtRatioAtTick(MAX_TICK)
    uint160 internal constant MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342;

    /// @notice Calculates sqrt(1.0001^tick) * 2^96
    /// @dev Throws if |tick| > max tick
    /// @param tick The input tick for the above formula
    /// @return sqrtPriceX96 A Fixed point Q64.96 number representing the sqrt of the ratio of the two assets (token1/token0)
    /// at the given tick
    function getSqrtRatioAtTick(int24 tick) internal pure returns (uint160 sqrtPriceX96) {
        uint256 absTick = tick < 0 ? uint256(-int256(tick)) : uint256(int256(tick));
        require(absTick <= uint256(int256(MAX_TICK)), 'T');

        uint256 ratio = absTick & 0x1 != 0 ? 0xfffcb933bd6fad37aa2d162d1a594001 : 0x100000000000000000000000000000000;
        if (absTick & 0x2 != 0) ratio = (ratio * 0xfff97272373d413259a46990580e213a) >> 128;
        if (absTick & 0x4 != 0) ratio = (ratio * 0xfff2e50f5f656932ef12357cf3c7fdcc) >> 128;
        if (absTick & 0x8 != 0) ratio = (ratio * 0xffe5caca7e10e4e61c3624eaa0941cd0) >> 128;
        if (absTick & 0x10 != 0) ratio = (ratio * 0xffcb9843d60f6159c9db58835c926644) >> 128;
        if (absTick & 0x20 != 0) ratio = (ratio * 0xff973b41fa98c081472e6896dfb254c0) >> 128;
        if (absTick & 0x40 != 0) ratio = (ratio * 0xff2ea16466c96a3843ec78b326b52861) >> 128;
        if (absTick & 0x80 != 0) ratio = (ratio * 0xfe5dee046a99a2a811c461f1969c3053) >> 128;
        if (absTick & 0x100 != 0) ratio = (ratio * 0xfcbe86c7900a88aedcffc83b479aa3a4) >> 128;
        if (absTick & 0x200 != 0) ratio = (ratio * 0xf987a7253ac413176f2b074cf7815e54) >> 128;
        if (absTick & 0x400 != 0) ratio = (ratio * 0xf3392b0822b70005940c7a398e4b70f3) >> 128;
        if (absTick & 0x800 != 0) ratio = (ratio * 0xe7159475a2c29b7443b29c7fa6e889d9) >> 128;
        if (absTick & 0x1000 != 0) ratio = (ratio * 0xd097f3bdfd2022b8845ad8f792aa5825) >> 128;
        if (absTick & 0x2000 != 0) ratio = (ratio * 0xa9f746462d870fdf8a65dc1f90e061e5) >> 128;
        if (absTick & 0x4000 != 0) ratio = (ratio * 0x70d869a156d2a1b890bb3df62baf32f7) >> 128;
        if (absTick & 0x8000 != 0) ratio = (ratio * 0x31be135f97d08fd981231505542fcfa6) >> 128;
        if (absTick & 0x10000 != 0) ratio = (ratio * 0x9aa508b5b7a84e1c677de54f3e99bc9) >> 128;
        if (absTick & 0x20000 != 0) ratio = (ratio * 0x5d6af8dedb81196699c329225ee604) >> 128;
        if (absTick & 0x40000 != 0) ratio = (ratio * 0x2216e584f5fa1ea926041bedfe98) >> 128;
        if (absTick & 0x80000 != 0) ratio = (ratio * 0x48a170391f7dc42444e8fa2) >> 128;

        if (tick > 0) ratio = type(uint256).max / ratio;

        // this divides by 1<<32 rounding up to go from a Q128.128 to a Q128.96.
        // we then downcast because we know the result always fits within 160 bits due to our tick input constraint
        // we round up in the division so getTickAtSqrtRatio of the output price is always consistent
        sqrtPriceX96 = uint160((ratio >> 32) + (ratio % (1 << 32) == 0 ? 0 : 1));
    }

}

contracts/StakedTwapKeeper.sol.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity 0.8.24;
import "./AutomationSupport.sol";
import "./StakedFullMath.sol";
import "./StakedTickMath.sol";

interface TwapV3Factory { function getPool(address, address, uint24) external view returns (address); }
interface TwapV3Pool {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function fee() external view returns (uint24);
    function liquidity() external view returns (uint128);
    function slot0() external view returns (uint160, int24, uint16, uint16, uint16, uint8, bool);
    function observations(uint256) external view returns (uint32, int56, uint160, bool);
    function observe(uint32[] calldata) external view returns (int56[] memory, uint160[] memory);
}
interface TwapDistributor {
    function owner() external view returns (address);
    function keeper() external view returns (address);
    function vault() external view returns (address);
    function swapRouter() external view returns (address);
    function bnkrWethFee() external view returns (uint24);
    function wethUsdcFee() external view returns (uint24);
    function liquidityWallet() external view returns (address);
    function bnkrStakingWallet() external view returns (address);
    function bnkr() external view returns (address);
    function weth() external view returns (address);
    function usdc() external view returns (address);
    function minBnkrBatch() external view returns (uint256);
    function pendingSwapBnkr() external view returns (uint256);
    function swapAndNotify(uint256) external returns (uint256);
}

/// @notice Distribution-only keeper. No custody, token approvals, buyback or arbitrary call path.
/// @dev A DEX TWAP is not manipulation-proof. Limits restrict, but cannot eliminate, oracle/MEV risk.
contract StakedTwapKeeper is SafeAuthority {
    uint32 public constant LONG_WINDOW = 1 hours;
    uint32 public constant SHORT_WINDOW = 5 minutes;
    uint32 public constant MAX_OBSERVATION_AGE = 30 minutes;
    uint32 public constant MAX_DEADLINE = 120;
    uint24 public constant FEE_BNKR_WETH = 10000;
    uint24 public constant FEE_WETH_USDC = 500;
    uint256 private constant Q96 = 1 << 96;
    uint256 private constant DAY = 1 days;
    uint256 private constant MAX_TRADES = 96;

    struct Config { address distributor; address relay; address bnkr; address weth; address usdc; address router; address factory; }
    struct Limits {
        uint128 maxBnkrPerSwap;
        uint128 maxBnkrPer24Hours;
        uint128 minLiquidityBnkrWeth;
        uint128 minLiquidityWethUsdc;
        uint32 minInterval;
        uint16 slippageBps;
        uint16 maxTickDeviation;
        uint16 maxInputReserveBps;
    }
    struct Reading { int24 longTick; int24 shortTick; uint160 sqrtPriceX96; uint128 effectiveLiquidity; }
    struct Trade { uint48 timestamp; uint128 amount; }

    address public immutable distributor;
    address public immutable relay;
    address public immutable bnkr;
    address public immutable weth;
    address public immutable usdc;
    address public immutable router;
    address public immutable factory;
    address public immutable poolBnkrWeth;
    address public immutable poolWethUsdc;
    address public operator;
    bool public paused = true;
    Limits public limits;
    uint256 public nonce;
    uint48 public lastExecution;
    Trade[96] public history;
    uint8 public nextTrade;

    event OperatorUpdated(address indexed operator);
    event LimitsUpdated(Limits limits);
    event Paused(bool paused);
    event Executed(uint256 indexed nonce, uint128 bnkrIn, uint256 minimumUsdc, uint256 usdcOut);

    constructor(address safe_, Config memory c) SafeAuthority(safe_) {
        require(c.distributor.code.length > 0 && c.relay.code.length > 0, "missing protocol");
        require(c.router.code.length > 0 && c.factory.code.length > 0, "missing DEX");
        require(c.bnkr.code.length > 0 && c.weth.code.length > 0 && c.usdc.code.length > 0, "missing tokens");
        require(c.bnkr != c.weth && c.bnkr != c.usdc && c.weth != c.usdc, "duplicate tokens");
        distributor = c.distributor; relay = c.relay; bnkr = c.bnkr; weth = c.weth; usdc = c.usdc;
        router = c.router; factory = c.factory;
        poolBnkrWeth = _pool(c.factory, c.bnkr, c.weth, FEE_BNKR_WETH);
        poolWethUsdc = _pool(c.factory, c.weth, c.usdc, FEE_WETH_USDC);
    }

    function _pool(address f, address a, address b, uint24 fee_) private view returns (address p) {
        p = TwapV3Factory(f).getPool(a, b, fee_);
        require(p.code.length > 0, "missing pool");
        require(TwapV3Pool(p).token0() == (a < b ? a : b) && TwapV3Pool(p).token1() == (a < b ? b : a), "wrong pool tokens");
        require(TwapV3Pool(p).fee() == fee_, "wrong pool fee");
    }

    function setOperator(address value) external onlySafe { operator = value; nonce++; emit OperatorUpdated(value); }

    function setLimits(Limits calldata p) external onlySafe {
        require(paused, "pause first");
        require(p.maxBnkrPerSwap > 0 && p.maxBnkrPer24Hours >= p.maxBnkrPerSwap, "bad caps");
        require(p.minLiquidityBnkrWeth > 0 && p.minLiquidityWethUsdc > 0, "zero liquidity floor");
        require(p.minInterval >= 15 minutes && p.minInterval <= 1 days, "bad interval");
        require(p.slippageBps <= 100 && p.maxTickDeviation > 0 && p.maxTickDeviation <= 100, "loose price limits");
        require(p.maxInputReserveBps > 0 && p.maxInputReserveBps <= 20, "loose size limit");
        limits = p; nonce++; // History and lastExecution deliberately survive every configuration change.
        emit LimitsUpdated(p);
    }

    function setPaused(bool value) external {
        require(msg.sender == safe || (msg.sender == operator && value), "not Safe");
        if (!value) {
            require(operator != address(0) && limits.maxBnkrPerSwap > 0, "not configured");
            _routeOkay();
        }
        paused = value; nonce++; emit Paused(value);
    }

    function spentLast24Hours() public view returns (uint256 spent) {
        for (uint256 i; i < MAX_TRADES; ++i) {
            Trade memory t = history[i];
            if (uint256(t.timestamp) + DAY > block.timestamp) spent += t.amount;
        }
    }

    function _routeOkay() private view {
        TwapDistributor d = TwapDistributor(distributor);
        require(d.owner() == safe && d.keeper() == address(this), "authority changed");
        require(d.vault() == relay && d.swapRouter() == router, "route changed");
        require(d.bnkr() == bnkr && d.weth() == weth && d.usdc() == usdc, "tokens changed");
        require(d.bnkrWethFee() == FEE_BNKR_WETH && d.wethUsdcFee() == FEE_WETH_USDC, "fees changed");
        require(d.liquidityWallet() == safe && d.bnkrStakingWallet() == safe, "payout changed");
    }

    // Uniswap v3 OracleLibrary consult semantics, including wraparound and negative-tick rounding.
    function _mean(int56 before_, int56 after_, uint32 seconds_) private pure returns (int24 tick) {
        int56 delta;
        unchecked { delta = after_ - before_; }
        int56 divisor = int56(uint56(seconds_));
        int56 value = delta / divisor;
        if (delta < 0 && delta % divisor != 0) --value;
        require(value >= -887272 && value <= 887272, "invalid mean tick");
        tick = int24(value);
    }

    function _near(int24 a, int24 b) private view {
        int256 delta = int256(a) - int256(b);
        require(delta <= int256(uint256(limits.maxTickDeviation)) && delta >= -int256(uint256(limits.maxTickDeviation)), "price deviation");
    }

    function _read(address pool, uint128 minimumLiquidity) private view returns (Reading memory r) {
        TwapV3Pool p = TwapV3Pool(pool);
        (uint160 sqrt, int24 spot, uint16 index, , , , bool unlocked) = p.slot0();
        require(unlocked && sqrt > 0, "pool locked/uninitialized");
        (uint32 last, , , bool initialized) = p.observations(index);
        uint32 age;
        unchecked { age = uint32(block.timestamp) - last; }
        require(initialized && age <= MAX_OBSERVATION_AGE, "stale pool");
        uint32[] memory secondsAgos = new uint32[](3);
        secondsAgos[0] = LONG_WINDOW; secondsAgos[1] = SHORT_WINDOW;
        (int56[] memory ticks, uint160[] memory spl) = p.observe(secondsAgos); // Missing history reverts, never falls back to spot.
        require(ticks.length == 3 && spl.length == 3, "invalid observation");
        r.longTick = _mean(ticks[0], ticks[2], LONG_WINDOW);
        r.shortTick = _mean(ticks[1], ticks[2], SHORT_WINDOW);
        _near(spot, r.longTick); _near(spot, r.shortTick); _near(r.longTick, r.shortTick);
        uint160 delta;
        unchecked { delta = spl[2] - spl[0]; }
        require(delta > 0, "invalid liquidity history");
        uint256 harmonic = (uint192(LONG_WINDOW) * type(uint160).max) / (uint192(delta) << 32);
        require(harmonic > 0 && harmonic <= type(uint128).max, "invalid harmonic liquidity");
        uint128 current = p.liquidity();
        r.effectiveLiquidity = current < harmonic ? current : uint128(harmonic);
        require(r.effectiveLiquidity >= minimumLiquidity, "thin liquidity");
        r.sqrtPriceX96 = sqrt;
    }

    function _quote(int24 tick, uint128 amount, address base, address quote) private pure returns (uint256) {
        uint160 sqrt = StakedTickMath.getSqrtRatioAtTick(tick);
        if (sqrt <= type(uint128).max) {
            uint256 ratio = uint256(sqrt) * sqrt;
            return base < quote ? StakedFullMath.mulDiv(ratio, amount, 1 << 192) : StakedFullMath.mulDiv(1 << 192, amount, ratio);
        }
        uint256 ratio128 = StakedFullMath.mulDiv(sqrt, sqrt, 1 << 64);
        return base < quote ? StakedFullMath.mulDiv(ratio128, amount, 1 << 128) : StakedFullMath.mulDiv(1 << 128, amount, ratio128);
    }

    function _net(uint256 amount, uint24 fee_) private pure returns (uint128) {
        require(amount > 0 && amount <= type(uint128).max, "quote overflow/zero");
        return uint128(StakedFullMath.mulDiv(amount, 1_000_000 - fee_, 1_000_000));
    }

    function _reserve(uint128 liquidity_, uint160 sqrt, bool token0) private pure returns (uint256) {
        return token0 ? StakedFullMath.mulDiv(liquidity_, Q96, sqrt) : StakedFullMath.mulDiv(liquidity_, sqrt, Q96);
    }

    function _size(Reading memory r, bool token0, uint256 amount) private view {
        uint256 a = _reserve(r.effectiveLiquidity, r.sqrtPriceX96, token0);
        uint256 b = _reserve(r.effectiveLiquidity, StakedTickMath.getSqrtRatioAtTick(r.longTick), token0);
        uint256 c = _reserve(r.effectiveLiquidity, StakedTickMath.getSqrtRatioAtTick(r.shortTick), token0);
        uint256 smallest = a < b ? a : b;
        if (c < smallest) smallest = c;
        require(amount <= StakedFullMath.mulDiv(smallest, limits.maxInputReserveBps, 10000), "input too large for liquidity");
    }

    function minimumUsdc(uint128 amount) public view returns (uint256 minimum) {
        require(amount > 0 && limits.maxBnkrPerSwap > 0, "zero/unconfigured");
        Reading memory a = _read(poolBnkrWeth, limits.minLiquidityBnkrWeth);
        Reading memory b = _read(poolWethUsdc, limits.minLiquidityWethUsdc);
        _size(a, bnkr < weth, amount);
        uint128 netBnkr = _net(amount, FEE_BNKR_WETH);
        uint256 longWeth = _quote(a.longTick, netBnkr, bnkr, weth);
        uint256 shortWeth = _quote(a.shortTick, netBnkr, bnkr, weth);
        uint256 largerWeth = longWeth > shortWeth ? longWeth : shortWeth;
        _size(b, weth < usdc, largerWeth);
        uint256 longOut = _quote(b.longTick, _net(longWeth, FEE_WETH_USDC), weth, usdc);
        uint256 shortOut = _quote(b.shortTick, _net(shortWeth, FEE_WETH_USDC), weth, usdc);
        uint256 referenceOut = longOut > shortOut ? longOut : shortOut;
        require(referenceOut > 0, "empty quote");
        minimum = StakedFullMath.mulDivRoundingUp(referenceOut, 10000 - limits.slippageBps, 10000);
    }

    function swapAndNotify(uint128 expectedAmount, uint256 keeperMinimum, uint48 deadline, uint256 expectedNonce)
        external nonReentrant returns (uint256 out)
    {
        require(msg.sender == operator || msg.sender == safe, "not operator");
        require(!paused && expectedNonce == nonce, "paused/stale nonce");
        // The price floor is recomputed on-chain at execution; no caller-supplied quote-block attestation.
        require(deadline >= block.timestamp && deadline <= block.timestamp + MAX_DEADLINE, "bad deadline");
        _routeOkay();
        require(expectedAmount > 0 && expectedAmount == TwapDistributor(distributor).pendingSwapBnkr(), "batch changed");
        require(expectedAmount >= TwapDistributor(distributor).minBnkrBatch(), "below batch threshold");
        require(expectedAmount <= limits.maxBnkrPerSwap && spentLast24Hours() + expectedAmount <= limits.maxBnkrPer24Hours, "spending cap");
        require(block.timestamp >= uint256(lastExecution) + limits.minInterval, "cooldown");
        uint256 floor = minimumUsdc(expectedAmount);
        require(keeperMinimum >= floor, "below TWAP floor");
        require(history[nextTrade].amount == 0 || uint256(history[nextTrade].timestamp) + DAY <= block.timestamp, "history full");
        history[nextTrade] = Trade(uint48(block.timestamp), expectedAmount);
        nextTrade = uint8((uint256(nextTrade) + 1) % MAX_TRADES);
        lastExecution = uint48(block.timestamp);
        nonce++;
        out = TwapDistributor(distributor).swapAndNotify(keeperMinimum);
        require(out >= keeperMinimum, "under-delivery");
        emit Executed(expectedNonce, expectedAmount, keeperMinimum, out);
    }
}

contracts/StakedTwapKeeperV3.sol.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity 0.8.24;
import "./AutomationSupport.sol";
import "./StakedFullMath.sol";
import "./StakedTickMath.sol";
import {TwapV3Factory, TwapV3Pool, TwapDistributor} from "./StakedTwapKeeper.sol";

interface TwapPredecessor {
    function safe() external view returns (address);
    function bnkr() external view returns (address);
    function paused() external view returns (bool);
    function operator() external view returns (address);
    function spentLast24Hours() external view returns (uint256);
    function lastExecution() external view returns (uint48);
}

interface TwapBatchDistributor is TwapDistributor {
    function batchSwapVersion() external view returns (uint256);
    function swapBatchAndNotify(uint256 amountIn, uint256 minUsdcOut) external returns (uint256);
}

/// @notice Proposed, undeployed V3 distribution-only keeper with exact bounded batch inputs. No custody, token approvals, buyback or arbitrary call path.
/// @dev A DEX TWAP is not manipulation-proof. Limits restrict, but cannot eliminate, oracle/MEV risk.
contract StakedTwapKeeperV3 is SafeAuthority {
    uint32 public constant LONG_WINDOW = 1 hours;
    uint32 public constant SHORT_WINDOW = 5 minutes;
    uint32 public constant MAX_OBSERVATION_AGE = 30 minutes;
    uint32 public constant MAX_DEADLINE = 120;
    uint24 public constant FEE_BNKR_WETH = 10000;
    uint24 public constant FEE_WETH_USDC = 500;
    uint256 private constant Q96 = 1 << 96;
    uint256 private constant DAY = 1 days;
    uint256 private constant MAX_TRADES = 96;

    struct Config { address distributor; address relay; address bnkr; address weth; address usdc; address router; address factory; address predecessor; }
    struct Limits {
        uint128 maxBnkrPerSwap;
        uint128 maxBnkrPer24Hours;
        uint128 minLiquidityBnkrWeth;
        uint128 minLiquidityWethUsdc;
        uint32 minInterval;
        uint16 slippageBps;
        uint16 maxTickDeviation;
        uint16 maxInputReserveBps;
    }
    struct Reading { int24 longTick; int24 shortTick; uint160 sqrtPriceX96; uint128 effectiveLiquidity; }
    struct Trade { uint48 timestamp; uint128 amount; }

    address public immutable predecessor;
    address public immutable distributor;
    address public immutable relay;
    address public immutable bnkr;
    address public immutable weth;
    address public immutable usdc;
    address public immutable router;
    address public immutable factory;
    address public immutable poolBnkrWeth;
    address public immutable poolWethUsdc;
    address public operator;
    bool public paused = true;
    Limits public limits;
    uint256 public nonce;
    uint48 public lastExecution;
    Trade[96] public history;
    uint8 public nextTrade;

    event OperatorUpdated(address indexed operator);
    event LimitsUpdated(Limits limits);
    event Paused(bool paused);
    event Executed(uint256 indexed nonce, uint128 bnkrIn, uint256 minimumUsdc, uint256 usdcOut);

    constructor(address safe_, Config memory c) SafeAuthority(safe_) {
        require(c.distributor.code.length > 0 && c.relay.code.length > 0, "missing protocol");
        require(TwapBatchDistributor(c.distributor).batchSwapVersion() == 1, "batch interface required");
        require(c.router.code.length > 0 && c.factory.code.length > 0, "missing DEX");
        require(c.bnkr.code.length > 0 && c.weth.code.length > 0 && c.usdc.code.length > 0, "missing tokens");
        require(c.bnkr != c.weth && c.bnkr != c.usdc && c.weth != c.usdc, "duplicate tokens");
        distributor = c.distributor; relay = c.relay; bnkr = c.bnkr; weth = c.weth; usdc = c.usdc;
        router = c.router; factory = c.factory;
        require(c.predecessor.code.length > 0, "missing predecessor");
        require(TwapPredecessor(c.predecessor).safe() == safe_ && TwapPredecessor(c.predecessor).bnkr() == c.bnkr, "wrong predecessor");
        predecessor = c.predecessor;
        poolBnkrWeth = _pool(c.factory, c.bnkr, c.weth, FEE_BNKR_WETH);
        poolWethUsdc = _pool(c.factory, c.weth, c.usdc, FEE_WETH_USDC);
    }

    function _pool(address f, address a, address b, uint24 fee_) private view returns (address p) {
        p = TwapV3Factory(f).getPool(a, b, fee_);
        require(p.code.length > 0, "missing pool");
        require(TwapV3Pool(p).token0() == (a < b ? a : b) && TwapV3Pool(p).token1() == (a < b ? b : a), "wrong pool tokens");
        require(TwapV3Pool(p).fee() == fee_, "wrong pool fee");
    }

    function setOperator(address value) external onlySafe { operator = value; nonce++; emit OperatorUpdated(value); }

    function setLimits(Limits calldata p) external onlySafe {
        require(paused, "pause first");
        require(p.maxBnkrPerSwap > 0 && p.maxBnkrPer24Hours >= p.maxBnkrPerSwap, "bad caps");
        require(p.minLiquidityBnkrWeth > 0 && p.minLiquidityWethUsdc > 0, "zero liquidity floor");
        require(p.minInterval >= 15 minutes && p.minInterval <= 1 days, "bad interval");
        require(p.slippageBps <= 100 && p.maxTickDeviation > 0 && p.maxTickDeviation <= 100, "loose price limits");
        require(p.maxInputReserveBps > 0 && p.maxInputReserveBps <= 20, "loose size limit");
        limits = p; nonce++; // History and lastExecution deliberately survive every configuration change.
        emit LimitsUpdated(p);
    }

    function setPaused(bool value) external {
        require(msg.sender == safe || (msg.sender == operator && value), "not Safe");
        if (!value) {
            require(operator != address(0) && limits.maxBnkrPerSwap > 0, "not configured");
            _routeOkay();
        }
        paused = value; nonce++; emit Paused(value);
    }

    /// @notice Aggregate rolling spend, including the immutable legacy keeper.
    function spentLast24Hours() public view returns (uint256 spent) {
        spent = TwapPredecessor(predecessor).spentLast24Hours();
        for (uint256 i; i < MAX_TRADES; ++i) {
            Trade memory t = history[i];
            if (uint256(t.timestamp) + DAY > block.timestamp) spent += t.amount;
        }
    }

    function effectiveLastExecution() public view returns (uint48) {
        uint48 previous = TwapPredecessor(predecessor).lastExecution();
        return previous > lastExecution ? previous : lastExecution;
    }

    function _routeOkay() private view {
        require(TwapPredecessor(predecessor).paused() && TwapPredecessor(predecessor).operator() == address(0), "predecessor active");
        TwapDistributor d = TwapDistributor(distributor);
        require(d.owner() == safe && d.keeper() == address(this), "authority changed");
        require(d.vault() == relay && d.swapRouter() == router, "route changed");
        require(d.bnkr() == bnkr && d.weth() == weth && d.usdc() == usdc, "tokens changed");
        require(d.bnkrWethFee() == FEE_BNKR_WETH && d.wethUsdcFee() == FEE_WETH_USDC, "fees changed");
        require(d.liquidityWallet() == safe && d.bnkrStakingWallet() == safe, "payout changed");
    }

    // Uniswap v3 OracleLibrary consult semantics, including wraparound and negative-tick rounding.
    function _mean(int56 before_, int56 after_, uint32 seconds_) private pure returns (int24 tick) {
        int56 delta;
        unchecked { delta = after_ - before_; }
        int56 divisor = int56(uint56(seconds_));
        int56 value = delta / divisor;
        if (delta < 0 && delta % divisor != 0) --value;
        require(value >= -887272 && value <= 887272, "invalid mean tick");
        tick = int24(value);
    }

    function _near(int24 a, int24 b) private view {
        int256 delta = int256(a) - int256(b);
        require(delta <= int256(uint256(limits.maxTickDeviation)) && delta >= -int256(uint256(limits.maxTickDeviation)), "price deviation");
    }

    function _read(address pool, uint128 minimumLiquidity) private view returns (Reading memory r) {
        TwapV3Pool p = TwapV3Pool(pool);
        (uint160 sqrt, int24 spot, uint16 index, , , , bool unlocked) = p.slot0();
        require(unlocked && sqrt > 0, "pool locked/uninitialized");
        (uint32 last, , , bool initialized) = p.observations(index);
        uint32 age;
        unchecked { age = uint32(block.timestamp) - last; }
        require(initialized && age <= MAX_OBSERVATION_AGE, "stale pool");
        uint32[] memory secondsAgos = new uint32[](3);
        secondsAgos[0] = LONG_WINDOW; secondsAgos[1] = SHORT_WINDOW;
        (int56[] memory ticks, uint160[] memory spl) = p.observe(secondsAgos); // Missing history reverts, never falls back to spot.
        require(ticks.length == 3 && spl.length == 3, "invalid observation");
        r.longTick = _mean(ticks[0], ticks[2], LONG_WINDOW);
        r.shortTick = _mean(ticks[1], ticks[2], SHORT_WINDOW);
        _near(spot, r.longTick); _near(spot, r.shortTick); _near(r.longTick, r.shortTick);
        uint160 delta;
        unchecked { delta = spl[2] - spl[0]; }
        require(delta > 0, "invalid liquidity history");
        uint256 harmonic = (uint192(LONG_WINDOW) * type(uint160).max) / (uint192(delta) << 32);
        require(harmonic > 0 && harmonic <= type(uint128).max, "invalid harmonic liquidity");
        uint128 current = p.liquidity();
        r.effectiveLiquidity = current < harmonic ? current : uint128(harmonic);
        require(r.effectiveLiquidity >= minimumLiquidity, "thin liquidity");
        r.sqrtPriceX96 = sqrt;
    }

    function _quote(int24 tick, uint128 amount, address base, address quote) private pure returns (uint256) {
        uint160 sqrt = StakedTickMath.getSqrtRatioAtTick(tick);
        if (sqrt <= type(uint128).max) {
            uint256 ratio = uint256(sqrt) * sqrt;
            return base < quote ? StakedFullMath.mulDiv(ratio, amount, 1 << 192) : StakedFullMath.mulDiv(1 << 192, amount, ratio);
        }
        uint256 ratio128 = StakedFullMath.mulDiv(sqrt, sqrt, 1 << 64);
        return base < quote ? StakedFullMath.mulDiv(ratio128, amount, 1 << 128) : StakedFullMath.mulDiv(1 << 128, amount, ratio128);
    }

    function _net(uint256 amount, uint24 fee_) private pure returns (uint128) {
        require(amount > 0 && amount <= type(uint128).max, "quote overflow/zero");
        return uint128(StakedFullMath.mulDiv(amount, 1_000_000 - fee_, 1_000_000));
    }

    function _reserve(uint128 liquidity_, uint160 sqrt, bool token0) private pure returns (uint256) {
        return token0 ? StakedFullMath.mulDiv(liquidity_, Q96, sqrt) : StakedFullMath.mulDiv(liquidity_, sqrt, Q96);
    }

    function _size(Reading memory r, bool token0, uint256 amount) private view {
        uint256 a = _reserve(r.effectiveLiquidity, r.sqrtPriceX96, token0);
        uint256 b = _reserve(r.effectiveLiquidity, StakedTickMath.getSqrtRatioAtTick(r.longTick), token0);
        uint256 c = _reserve(r.effectiveLiquidity, StakedTickMath.getSqrtRatioAtTick(r.shortTick), token0);
        uint256 smallest = a < b ? a : b;
        if (c < smallest) smallest = c;
        require(amount <= StakedFullMath.mulDiv(smallest, limits.maxInputReserveBps, 10000), "input too large for liquidity");
    }

    function minimumUsdc(uint128 amount) public view returns (uint256 minimum) {
        require(amount > 0 && limits.maxBnkrPerSwap > 0, "zero/unconfigured");
        Reading memory a = _read(poolBnkrWeth, limits.minLiquidityBnkrWeth);
        Reading memory b = _read(poolWethUsdc, limits.minLiquidityWethUsdc);
        _size(a, bnkr < weth, amount);
        uint128 netBnkr = _net(amount, FEE_BNKR_WETH);
        uint256 longWeth = _quote(a.longTick, netBnkr, bnkr, weth);
        uint256 shortWeth = _quote(a.shortTick, netBnkr, bnkr, weth);
        uint256 largerWeth = longWeth > shortWeth ? longWeth : shortWeth;
        _size(b, weth < usdc, largerWeth);
        uint256 longOut = _quote(b.longTick, _net(longWeth, FEE_WETH_USDC), weth, usdc);
        uint256 shortOut = _quote(b.shortTick, _net(shortWeth, FEE_WETH_USDC), weth, usdc);
        uint256 referenceOut = longOut > shortOut ? longOut : shortOut;
        require(referenceOut > 0, "empty quote");
        minimum = StakedFullMath.mulDivRoundingUp(referenceOut, 10000 - limits.slippageBps, 10000);
    }

    /// @notice Swap this exact input; excess queued donations wait for a later bounded batch.
    function swapAndNotify(uint128 expectedAmount, uint256 keeperMinimum, uint48 deadline, uint256 expectedNonce)
        external nonReentrant returns (uint256 out)
    {
        require(msg.sender == operator || msg.sender == safe, "not operator");
        require(!paused && expectedNonce == nonce, "paused/stale nonce");
        // The price floor is recomputed on-chain at execution; no caller-supplied quote-block attestation.
        require(deadline >= block.timestamp && deadline <= block.timestamp + MAX_DEADLINE, "bad deadline");
        _routeOkay();
        require(expectedAmount > 0 && expectedAmount <= TwapDistributor(distributor).pendingSwapBnkr(), "insufficient queue");
        require(expectedAmount >= TwapDistributor(distributor).minBnkrBatch(), "below batch threshold");
        require(expectedAmount <= limits.maxBnkrPerSwap && spentLast24Hours() + expectedAmount <= limits.maxBnkrPer24Hours, "spending cap");
        require(block.timestamp >= uint256(effectiveLastExecution()) + limits.minInterval, "cooldown");
        uint256 floor = minimumUsdc(expectedAmount);
        require(keeperMinimum >= floor, "below TWAP floor");
        require(history[nextTrade].amount == 0 || uint256(history[nextTrade].timestamp) + DAY <= block.timestamp, "history full");
        history[nextTrade] = Trade(uint48(block.timestamp), expectedAmount);
        nextTrade = uint8((uint256(nextTrade) + 1) % MAX_TRADES);
        lastExecution = uint48(block.timestamp);
        nonce++;
        out = TwapBatchDistributor(distributor).swapBatchAndNotify(expectedAmount, keeperMinimum);
        require(out >= keeperMinimum, "under-delivery");
        emit Executed(expectedNonce, expectedAmount, keeperMinimum, out);
    }
}

contracts/StakedVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/**
 * @title StakedVault (v2)
 * @notice Dual-reward (USDC + BNKR) staking vault for $STAKED on Base.
 *
 *  - Staking token: $STAKED (0x731d4066a8375fc590fcd9dfe8d9e58670cb8ba3)
 *  - Reward tokens: USDC (6 dec) and BNKR (18 dec), streamed Synthetix-style over rolling 7-day windows
 *  - Lock: 7 days from the LAST deposit. Any top-up resets the timer for the wallet's entire balance.
 *  - Rewards accrue from day one but are only claimable once the lock has matured.
 *  - Early exit (withdraw before lockEnd):
 *      * 20% of the withdrawn principal is burned to 0xdead, 80% returned
 *      * 100% of accrued-but-unclaimed rewards are forfeited
 *      * forfeited USDC is moved into `buybackReserve`; the keeper executes a buy-and-burn of $STAKED through a
 *        pluggable IBuybackExecutor with a caller-supplied minimum output (slippage protection)
 *      * forfeited BNKR is re-streamed to the remaining stakers
 *  - Rewards that stream while nobody is staked are tracked in `undistributed` and can be re-streamed by anyone
 *
 *  Precision: reward rates are scaled by 1e18 and rewardPerToken by another 1e18 (1e36 total) so a 6-decimal
 *  reward token streamed against a 100B-supply 18-decimal staking token never rounds to zero.
 */

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface IBuybackExecutor {
    /// @dev Must pull `usdcAmount` USDC from msg.sender (the vault approves first), swap it for $STAKED and
    ///      send the $STAKED back to msg.sender. The vault verifies the delivered amount against `minStakedOut`.
    function buyback(uint256 usdcAmount, uint256 minStakedOut) external returns (uint256 stakedOut);
}

library SafeERC20Lite {
    function safeTransfer(IERC20 token, address to, uint256 amount) internal {
        _call(address(token), abi.encodeWithSelector(token.transfer.selector, to, amount));
    }

    function safeTransferFrom(IERC20 token, address from, address to, uint256 amount) internal {
        _call(address(token), abi.encodeWithSelector(token.transferFrom.selector, from, to, amount));
    }

    function safeApprove(IERC20 token, address spender, uint256 amount) internal {
        _call(address(token), abi.encodeWithSelector(token.approve.selector, spender, amount));
    }

    function _call(address token, bytes memory data) private {
        (bool ok, bytes memory ret) = token.call(data);
        require(ok && (ret.length == 0 || abi.decode(ret, (bool))), "SafeERC20: operation failed");
    }
}

abstract contract Ownable2Step {
    address public owner;
    address public pendingOwner;

    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor(address initialOwner) {
        require(initialOwner != address(0), "owner=0");
        owner = initialOwner;
        emit OwnershipTransferred(address(0), initialOwner);
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    function acceptOwnership() external {
        require(msg.sender == pendingOwner, "not pending owner");
        emit OwnershipTransferred(owner, pendingOwner);
        owner = pendingOwner;
        pendingOwner = address(0);
    }
}

abstract contract ReentrancyGuard {
    uint256 private _status = 1;

    modifier nonReentrant() {
        require(_status == 1, "reentrant");
        _status = 2;
        _;
        _status = 1;
    }
}

contract StakedVault is Ownable2Step, ReentrancyGuard {
    using SafeERC20Lite for IERC20;

    // ---------------------------------------------------------------------
    // Immutables & constants
    // ---------------------------------------------------------------------
    IERC20 public immutable stakedToken;
    IERC20 public immutable usdc;
    IERC20 public immutable bnkr;

    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    uint256 public constant RATE_PRECISION = 1e18; // rewardRate is scaled by this
    uint256 public constant LOCK_DURATION = 7 days;
    uint256 public constant EARLY_EXIT_PENALTY_BPS = 2000; // 20%
    uint256 public constant BPS = 10_000;

    // ---------------------------------------------------------------------
    // Reward accounting
    // ---------------------------------------------------------------------
    struct Reward {
        uint256 periodFinish;
        uint256 rewardRate; // scaled by RATE_PRECISION (token-wei * 1e18 per second)
        uint256 lastUpdateTime;
        uint256 rewardPerTokenStored; // scaled by 1e36
        uint256 undistributed; // streamed while totalSupply == 0, or forfeited BNKR; re-streamable
    }

    uint256 public rewardsDuration = 7 days;
    mapping(address => Reward) public rewardData;
    mapping(address => mapping(address => uint256)) public userRewardPerTokenPaid;
    mapping(address => mapping(address => uint256)) public rewards;

    // ---------------------------------------------------------------------
    // Staking state
    // ---------------------------------------------------------------------
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => uint256) public lockEnd;

    // ---------------------------------------------------------------------
    // Roles & buyback
    // ---------------------------------------------------------------------
    address public distributor;
    address public keeper;
    IBuybackExecutor public buybackExecutor;
    uint256 public buybackReserve; // USDC earmarked for buy-and-burn

    // Lifetime stats (for the frontend)
    uint256 public totalPenaltyBurned;
    uint256 public totalBuybackBurned;
    uint256 public totalUsdcForfeited;
    uint256 public totalBnkrForfeited;
    uint256 public totalUsdcSpentOnBuyback;

    // ---------------------------------------------------------------------
    // Events
    // ---------------------------------------------------------------------
    event Staked(address indexed user, uint256 amount, uint256 newLockEnd);
    event Withdrawn(address indexed user, uint256 amount);
    event EarlyExit(address indexed user, uint256 amountRequested, uint256 amountReturned, uint256 penaltyBurned, uint256 usdcForfeited, uint256 bnkrForfeited);
    event RewardPaid(address indexed user, address indexed token, uint256 amount);
    event RewardAdded(address indexed token, uint256 amount, uint256 periodFinish);
    event UndistributedRestreamed(address indexed token, uint256 amount);
    event BuybackExecuted(address indexed keeper, uint256 usdcIn, uint256 stakedBurned);
    event DistributorUpdated(address distributor);
    event KeeperUpdated(address keeper);
    event BuybackExecutorUpdated(address executor);
    event RewardsDurationUpdated(uint256 duration);
    event Recovered(address token, uint256 amount);

    // ---------------------------------------------------------------------
    // Constructor
    // ---------------------------------------------------------------------
    constructor(address _stakedToken, address _usdc, address _bnkr, address _owner) Ownable2Step(_owner) {
        require(_stakedToken != address(0) && _usdc != address(0) && _bnkr != address(0), "token=0");
        require(_stakedToken != _usdc && _stakedToken != _bnkr && _usdc != _bnkr, "dup token");
        stakedToken = IERC20(_stakedToken);
        usdc = IERC20(_usdc);
        bnkr = IERC20(_bnkr);
    }

    // ---------------------------------------------------------------------
    // Modifiers
    // ---------------------------------------------------------------------
    modifier updateReward(address account) {
        _updateReward(address(usdc), account);
        _updateReward(address(bnkr), account);
        _;
    }

    modifier onlyKeeperOrOwner() {
        require(msg.sender == keeper || msg.sender == owner, "not keeper");
        _;
    }

    // ---------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------
    function isRewardToken(address token) public view returns (bool) {
        return token == address(usdc) || token == address(bnkr);
    }

    function lastTimeRewardApplicable(address token) public view returns (uint256) {
        uint256 finish = rewardData[token].periodFinish;
        return block.timestamp < finish ? block.timestamp : finish;
    }

    function rewardPerToken(address token) public view returns (uint256) {
        Reward storage r = rewardData[token];
        if (totalSupply == 0) return r.rewardPerTokenStored;
        uint256 dt = lastTimeRewardApplicable(token) - r.lastUpdateTime;
        return r.rewardPerTokenStored + (dt * r.rewardRate * 1e18) / totalSupply;
    }

    function earned(address token, address account) public view returns (uint256) {
        return (balanceOf[account] * (rewardPerToken(token) - userRewardPerTokenPaid[token][account])) / 1e36
            + rewards[token][account];
    }

    /// @notice Tokens streamed per full rewardsDuration at the current rate (unscaled token units).
    function getRewardForDuration(address token) external view returns (uint256) {
        return (rewardData[token].rewardRate * rewardsDuration) / RATE_PRECISION;
    }

    /// @notice Tokens streamed per second at the current rate, scaled by 1e18 (for APR math on the frontend).
    function rewardRatePerSecond(address token) external view returns (uint256) {
        return block.timestamp < rewardData[token].periodFinish ? rewardData[token].rewardRate : 0;
    }

    function isLocked(address account) public view returns (bool) {
        return block.timestamp < lockEnd[account];
    }

    function timeUntilUnlock(address account) external view returns (uint256) {
        return block.timestamp < lockEnd[account] ? lockEnd[account] - block.timestamp : 0;
    }

    /// @notice What a wallet would receive / lose if it withdrew `amount` right now.
    function previewWithdraw(address account, uint256 amount)
        external
        view
        returns (uint256 returned, uint256 penalty, uint256 usdcForfeited, uint256 bnkrForfeited)
    {
        if (block.timestamp >= lockEnd[account]) return (amount, 0, 0, 0);
        penalty = (amount * EARLY_EXIT_PENALTY_BPS) / BPS;
        returned = amount - penalty;
        usdcForfeited = earned(address(usdc), account);
        bnkrForfeited = earned(address(bnkr), account);
    }

    // ---------------------------------------------------------------------
    // User actions
    // ---------------------------------------------------------------------
    function stake(uint256 amount) external nonReentrant updateReward(msg.sender) {
        require(amount > 0, "amount=0");
        uint256 before = stakedToken.balanceOf(address(this));
        stakedToken.safeTransferFrom(msg.sender, address(this), amount);
        uint256 received = stakedToken.balanceOf(address(this)) - before;
        require(received > 0, "nothing received");

        totalSupply += received;
        balanceOf[msg.sender] += received;
        uint256 newLockEnd = block.timestamp + LOCK_DURATION;
        lockEnd[msg.sender] = newLockEnd;
        emit Staked(msg.sender, received, newLockEnd);
    }

    /// @notice Withdraw principal. Before lockEnd this is an early exit: 20% burned + all accrued rewards forfeited.
    function withdraw(uint256 amount) external nonReentrant updateReward(msg.sender) {
        _withdraw(amount);
    }

    /// @notice Claim accrued USDC + BNKR. Only possible once the 7-day lock has matured.
    function getReward() external nonReentrant updateReward(msg.sender) {
        _getReward();
    }

    /// @notice Withdraw everything and (if unlocked) claim rewards in one tx.
    function exit() external nonReentrant updateReward(msg.sender) {
        _withdraw(balanceOf[msg.sender]);
        if (block.timestamp >= lockEnd[msg.sender]) _getReward();
    }

    function _withdraw(uint256 amount) internal {
        require(amount > 0, "amount=0");
        require(amount <= balanceOf[msg.sender], "exceeds balance");

        totalSupply -= amount;
        balanceOf[msg.sender] -= amount;

        if (block.timestamp >= lockEnd[msg.sender]) {
            stakedToken.safeTransfer(msg.sender, amount);
            emit Withdrawn(msg.sender, amount);
            return;
        }

        // ---- early exit ----
        uint256 penalty = (amount * EARLY_EXIT_PENALTY_BPS) / BPS;
        uint256 returned = amount - penalty;

        uint256 usdcForfeited = rewards[address(usdc)][msg.sender];
        uint256 bnkrForfeited = rewards[address(bnkr)][msg.sender];
        rewards[address(usdc)][msg.sender] = 0;
        rewards[address(bnkr)][msg.sender] = 0;

        buybackReserve += usdcForfeited; // USDC stays in the vault, earmarked for buy-and-burn
        rewardData[address(bnkr)].undistributed += bnkrForfeited; // re-streamed to loyal stakers
        totalPenaltyBurned += penalty;
        totalUsdcForfeited += usdcForfeited;
        totalBnkrForfeited += bnkrForfeited;

        if (penalty > 0) stakedToken.safeTransfer(DEAD, penalty);
        stakedToken.safeTransfer(msg.sender, returned);
        emit EarlyExit(msg.sender, amount, returned, penalty, usdcForfeited, bnkrForfeited);
    }

    function _getReward() internal {
        require(block.timestamp >= lockEnd[msg.sender], "locked");
        uint256 u = rewards[address(usdc)][msg.sender];
        if (u > 0) {
            rewards[address(usdc)][msg.sender] = 0;
            usdc.safeTransfer(msg.sender, u);
            emit RewardPaid(msg.sender, address(usdc), u);
        }
        uint256 b = rewards[address(bnkr)][msg.sender];
        if (b > 0) {
            rewards[address(bnkr)][msg.sender] = 0;
            bnkr.safeTransfer(msg.sender, b);
            emit RewardPaid(msg.sender, address(bnkr), b);
        }
    }

    // ---------------------------------------------------------------------
    // Reward funding
    // ---------------------------------------------------------------------
    /// @notice Pull `amount` of `token` from the caller and stream it over rewardsDuration.
    ///         Callable by the distributor (USDC leg) or the owner (BNKR staking yield leg).
    function notifyRewardAmount(address token, uint256 amount) external nonReentrant updateReward(address(0)) {
        require(msg.sender == distributor || msg.sender == owner, "not authorized");
        require(isRewardToken(token), "not reward token");
        require(amount > 0, "amount=0");
        uint256 before = IERC20(token).balanceOf(address(this));
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        uint256 received = IERC20(token).balanceOf(address(this)) - before;
        _notifyReward(token, received);
    }

    /// @notice Re-stream rewards that accrued while nobody was staked (or forfeited BNKR). Permissionless.
    function restreamUndistributed(address token) external nonReentrant updateReward(address(0)) {
        require(isRewardToken(token), "not reward token");
        uint256 amount = rewardData[token].undistributed;
        require(amount > 0, "nothing to restream");
        rewardData[token].undistributed = 0;
        _notifyReward(token, amount);
        emit UndistributedRestreamed(token, amount);
    }

    function _notifyReward(address token, uint256 reward) internal {
        Reward storage r = rewardData[token];
        uint256 scaled = reward * RATE_PRECISION;
        if (block.timestamp >= r.periodFinish) {
            r.rewardRate = scaled / rewardsDuration;
        } else {
            uint256 leftover = (r.periodFinish - block.timestamp) * r.rewardRate;
            r.rewardRate = (scaled + leftover) / rewardsDuration;
        }

        // Solvency sanity check: the stream for the whole duration must be backed by un-earmarked balance.
        uint256 balance = IERC20(token).balanceOf(address(this));
        uint256 earmarked = r.undistributed + (token == address(usdc) ? buybackReserve : 0);
        uint256 available = balance > earmarked ? balance - earmarked : 0;
        require((r.rewardRate * rewardsDuration) / RATE_PRECISION <= available, "reward > balance");

        r.lastUpdateTime = block.timestamp;
        r.periodFinish = block.timestamp + rewardsDuration;
        emit RewardAdded(token, reward, r.periodFinish);
    }

    function _updateReward(address token, address account) internal {
        Reward storage r = rewardData[token];
        uint256 applicable = lastTimeRewardApplicable(token);
        if (totalSupply == 0) {
            if (applicable > r.lastUpdateTime) {
                r.undistributed += ((applicable - r.lastUpdateTime) * r.rewardRate) / RATE_PRECISION;
            }
        } else {
            r.rewardPerTokenStored = rewardPerToken(token);
        }
        r.lastUpdateTime = applicable;
        if (account != address(0)) {
            rewards[token][account] = earned(token, account);
            userRewardPerTokenPaid[token][account] = r.rewardPerTokenStored;
        }
    }

    // ---------------------------------------------------------------------
    // Buy-and-burn (keeper)
    // ---------------------------------------------------------------------
    /// @notice Spend `usdcAmount` of the buyback reserve on $STAKED via the executor and burn it.
    /// @param minStakedOut Minimum $STAKED the executor must deliver (keeper computes off-chain from a quote).
    function executeBuyback(uint256 usdcAmount, uint256 minStakedOut) external nonReentrant onlyKeeperOrOwner {
        require(address(buybackExecutor) != address(0), "executor unset");
        require(usdcAmount > 0 && usdcAmount <= buybackReserve, "bad amount");
        require(minStakedOut > 0, "minOut=0");

        buybackReserve -= usdcAmount;
        uint256 usdcBefore = usdc.balanceOf(address(this));
        uint256 stakedBefore = stakedToken.balanceOf(address(this));

        usdc.safeApprove(address(buybackExecutor), usdcAmount);
        buybackExecutor.buyback(usdcAmount, minStakedOut);
        usdc.safeApprove(address(buybackExecutor), 0);

        require(usdcBefore - usdc.balanceOf(address(this)) == usdcAmount, "usdc not consumed");
        uint256 delivered = stakedToken.balanceOf(address(this)) - stakedBefore;
        require(delivered >= minStakedOut, "slippage");

        totalBuybackBurned += delivered;
        totalUsdcSpentOnBuyback += usdcAmount;
        stakedToken.safeTransfer(DEAD, delivered);
        emit BuybackExecuted(msg.sender, usdcAmount, delivered);
    }

    // ---------------------------------------------------------------------
    // Admin
    // ---------------------------------------------------------------------
    function setDistributor(address _distributor) external onlyOwner {
        distributor = _distributor;
        emit DistributorUpdated(_distributor);
    }

    function setKeeper(address _keeper) external onlyOwner {
        keeper = _keeper;
        emit KeeperUpdated(_keeper);
    }

    function setBuybackExecutor(address _executor) external onlyOwner {
        buybackExecutor = IBuybackExecutor(_executor);
        emit BuybackExecutorUpdated(_executor);
    }

    /// @dev Only when both streams are finished, so an in-flight stream cannot be shortened or stretched.
    function setRewardsDuration(uint256 _duration) external onlyOwner {
        require(_duration >= 1 days && _duration <= 90 days, "bad duration");
        require(
            block.timestamp >= rewardData[address(usdc)].periodFinish
                && block.timestamp >= rewardData[address(bnkr)].periodFinish,
            "period active"
        );
        rewardsDuration = _duration;
        emit RewardsDurationUpdated(_duration);
    }

    /// @notice Recover tokens sent here by mistake. Staking and reward tokens can never be pulled.
    function recoverERC20(address token, uint256 amount, address to) external onlyOwner {
        require(token != address(stakedToken) && !isRewardToken(token), "protected");
        IERC20(token).safeTransfer(to, amount);
        emit Recovered(token, amount);
    }
}

contracts/StakedVaultV3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20, IBuybackExecutor, SafeERC20Lite, Ownable2Step, ReentrancyGuard} from "./StakedVault.sol";
import {ConfigurationDelay} from "./ConfigurationDelay.sol";

/// @notice Proposed replacement core. NOT the contract currently deployed on Base.
/// @dev Retains the v2 accounting and interfaces, with the reviewed v3 safety changes.
///      Listed configuration changes require 48 hours notice and expire 7 days later.
contract StakedVaultV3 is Ownable2Step, ReentrancyGuard, ConfigurationDelay {
    using SafeERC20Lite for IERC20;

    // ---------------------------------------------------------------------
    // Immutables & constants
    // ---------------------------------------------------------------------
    IERC20 public immutable stakedToken;
    IERC20 public immutable usdc;
    IERC20 public immutable bnkr;

    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    uint256 public constant RATE_PRECISION = 1e18; // rewardRate is scaled by this
    uint256 public constant LOCK_DURATION = 7 days;
    uint256 public constant EARLY_EXIT_PENALTY_BPS = 2000; // 20%
    uint256 public constant BPS = 10_000;

    // ---------------------------------------------------------------------
    // Reward accounting
    // ---------------------------------------------------------------------
    struct Reward {
        uint256 periodFinish;
        uint256 rewardRate; // scaled by RATE_PRECISION (token-wei * 1e18 per second)
        uint256 lastUpdateTime;
        uint256 rewardPerTokenStored; // scaled by 1e36
        uint256 undistributed; // streamed while totalSupply == 0, or forfeited BNKR; re-streamable
    }

    uint256 public rewardsDuration = 7 days;
    mapping(address => Reward) public rewardData;
    mapping(address => mapping(address => uint256)) public userRewardPerTokenPaid;
    mapping(address => mapping(address => uint256)) public rewards;

    // ---------------------------------------------------------------------
    // Staking state
    // ---------------------------------------------------------------------
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => uint256) public lockEnd;

    // ---------------------------------------------------------------------
    // Roles & buyback
    // ---------------------------------------------------------------------
    address public distributor;
    address public keeper;
    IBuybackExecutor public buybackExecutor;
    uint256 public buybackReserve; // USDC earmarked for buy-and-burn

    // Lifetime stats (for the frontend)
    uint256 public totalPenaltyBurned;
    uint256 public totalBuybackBurned;
    uint256 public totalUsdcForfeited;
    uint256 public totalBnkrForfeited;
    uint256 public totalUsdcSpentOnBuyback;

    // ---------------------------------------------------------------------
    // Events
    // ---------------------------------------------------------------------
    event Staked(address indexed user, uint256 amount, uint256 newLockEnd);
    event Withdrawn(address indexed user, uint256 amount);
    event EarlyExit(address indexed user, uint256 amountRequested, uint256 amountReturned, uint256 penaltyBurned, uint256 usdcForfeited, uint256 bnkrForfeited);
    event RewardPaid(address indexed user, address indexed token, uint256 amount);
    event RewardAdded(address indexed token, uint256 amount, uint256 periodFinish);
    event UndistributedRestreamed(address indexed token, uint256 amount);
    event BuybackExecuted(address indexed keeper, uint256 usdcIn, uint256 stakedBurned);
    event DistributorUpdated(address distributor);
    event KeeperUpdated(address keeper);
    event BuybackExecutorUpdated(address executor);
    event RewardsDurationUpdated(uint256 duration);
    event Recovered(address token, uint256 amount);

    // ---------------------------------------------------------------------
    // Constructor
    // ---------------------------------------------------------------------
    /// @dev Initial relay may be a reviewed, not-yet-deployed CREATE address.
    ///      Every later distributor change remains subject to ConfigurationDelay.
    constructor(address _stakedToken, address _usdc, address _bnkr, address _owner, address _initialDistributor) Ownable2Step(_owner) {
        require(_stakedToken != address(0) && _usdc != address(0) && _bnkr != address(0), "token=0");
        require(_stakedToken != _usdc && _stakedToken != _bnkr && _usdc != _bnkr, "dup token");
        stakedToken = IERC20(_stakedToken);
        usdc = IERC20(_usdc);
        bnkr = IERC20(_bnkr);
        distributor = _initialDistributor;
        emit DistributorUpdated(_initialDistributor);
    }

    // ---------------------------------------------------------------------
    // Modifiers
    // ---------------------------------------------------------------------
    modifier updateReward(address account) {
        _updateReward(address(usdc), account);
        _updateReward(address(bnkr), account);
        _;
    }

    modifier onlyKeeperOrOwner() {
        require(msg.sender == keeper || msg.sender == owner, "not keeper");
        _;
    }

    // ---------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------
    function isRewardToken(address token) public view returns (bool) {
        return token == address(usdc) || token == address(bnkr);
    }

    function lastTimeRewardApplicable(address token) public view returns (uint256) {
        uint256 finish = rewardData[token].periodFinish;
        return block.timestamp < finish ? block.timestamp : finish;
    }

    function rewardPerToken(address token) public view returns (uint256) {
        Reward storage r = rewardData[token];
        if (totalSupply == 0) return r.rewardPerTokenStored;
        uint256 dt = lastTimeRewardApplicable(token) - r.lastUpdateTime;
        return r.rewardPerTokenStored + (dt * r.rewardRate * 1e18) / totalSupply;
    }

    function earned(address token, address account) public view returns (uint256) {
        return (balanceOf[account] * (rewardPerToken(token) - userRewardPerTokenPaid[token][account])) / 1e36
            + rewards[token][account];
    }

    /// @notice Tokens streamed per full rewardsDuration at the current rate (unscaled token units).
    function getRewardForDuration(address token) external view returns (uint256) {
        return (rewardData[token].rewardRate * rewardsDuration) / RATE_PRECISION;
    }

    /// @notice Tokens streamed per second at the current rate, scaled by 1e18 (for APR math on the frontend).
    function rewardRatePerSecond(address token) external view returns (uint256) {
        return block.timestamp < rewardData[token].periodFinish ? rewardData[token].rewardRate : 0;
    }

    function isLocked(address account) public view returns (bool) {
        return block.timestamp < lockEnd[account];
    }

    function timeUntilUnlock(address account) external view returns (uint256) {
        return block.timestamp < lockEnd[account] ? lockEnd[account] - block.timestamp : 0;
    }

    /// @notice What a wallet would receive / lose if it withdrew `amount` right now.
    function previewWithdraw(address account, uint256 amount)
        external
        view
        returns (uint256 returned, uint256 penalty, uint256 usdcForfeited, uint256 bnkrForfeited)
    {
        if (block.timestamp >= lockEnd[account]) return (amount, 0, 0, 0);
        penalty = (amount * EARLY_EXIT_PENALTY_BPS) / BPS;
        returned = amount - penalty;
        usdcForfeited = earned(address(usdc), account);
        bnkrForfeited = earned(address(bnkr), account);
    }

    // ---------------------------------------------------------------------
    // User actions
    // ---------------------------------------------------------------------
    function stake(uint256 amount) external nonReentrant updateReward(msg.sender) {
        require(amount > 0, "amount=0");
        uint256 before = stakedToken.balanceOf(address(this));
        stakedToken.safeTransferFrom(msg.sender, address(this), amount);
        uint256 received = stakedToken.balanceOf(address(this)) - before;
        require(received > 0, "nothing received");

        totalSupply += received;
        balanceOf[msg.sender] += received;
        uint256 newLockEnd = block.timestamp + LOCK_DURATION;
        lockEnd[msg.sender] = newLockEnd;
        emit Staked(msg.sender, received, newLockEnd);
    }

    /// @notice Withdraw matured principal. Locked withdrawals must use earlyWithdraw explicitly.
    function withdraw(uint256 amount) external nonReentrant updateReward(msg.sender) {
        require(block.timestamp >= lockEnd[msg.sender], "locked");
        _withdraw(amount);
    }

    /// @notice Explicit early withdrawal: burns 20% of this amount and forfeits ALL account rewards.
    /// @dev Requires an active lock. At maturity use withdraw or exit instead.
    function earlyWithdraw(uint256 amount) external nonReentrant updateReward(msg.sender) {
        require(block.timestamp < lockEnd[msg.sender], "not locked");
        _withdraw(amount);
    }

    /// @notice Claim accrued USDC + BNKR. Only possible once the 7-day lock has matured.
    function getReward() external nonReentrant updateReward(msg.sender) {
        _getReward();
    }

    /// @notice Withdraw everything and claim rewards after maturity. Locked exits revert.
    /// @dev Explicit early withdrawals retain the documented penalty through earlyWithdraw(amount).
    function exit() external nonReentrant updateReward(msg.sender) {
        require(block.timestamp >= lockEnd[msg.sender], "locked");
        _withdraw(balanceOf[msg.sender]);
        _getReward();
    }

    function _withdraw(uint256 amount) internal {
        require(amount > 0, "amount=0");
        require(amount <= balanceOf[msg.sender], "exceeds balance");

        totalSupply -= amount;
        balanceOf[msg.sender] -= amount;

        if (block.timestamp >= lockEnd[msg.sender]) {
            stakedToken.safeTransfer(msg.sender, amount);
            emit Withdrawn(msg.sender, amount);
            return;
        }

        // ---- early exit ----
        uint256 penalty = (amount * EARLY_EXIT_PENALTY_BPS) / BPS;
        uint256 returned = amount - penalty;

        uint256 usdcForfeited = rewards[address(usdc)][msg.sender];
        uint256 bnkrForfeited = rewards[address(bnkr)][msg.sender];
        rewards[address(usdc)][msg.sender] = 0;
        rewards[address(bnkr)][msg.sender] = 0;

        buybackReserve += usdcForfeited; // USDC stays in the vault, earmarked for buy-and-burn
        rewardData[address(bnkr)].undistributed += bnkrForfeited; // re-streamed to loyal stakers
        totalPenaltyBurned += penalty;
        totalUsdcForfeited += usdcForfeited;
        totalBnkrForfeited += bnkrForfeited;

        if (penalty > 0) stakedToken.safeTransfer(DEAD, penalty);
        stakedToken.safeTransfer(msg.sender, returned);
        emit EarlyExit(msg.sender, amount, returned, penalty, usdcForfeited, bnkrForfeited);
    }

    function _getReward() internal {
        require(block.timestamp >= lockEnd[msg.sender], "locked");
        uint256 u = rewards[address(usdc)][msg.sender];
        if (u > 0) {
            rewards[address(usdc)][msg.sender] = 0;
            usdc.safeTransfer(msg.sender, u);
            emit RewardPaid(msg.sender, address(usdc), u);
        }
        uint256 b = rewards[address(bnkr)][msg.sender];
        if (b > 0) {
            rewards[address(bnkr)][msg.sender] = 0;
            bnkr.safeTransfer(msg.sender, b);
            emit RewardPaid(msg.sender, address(bnkr), b);
        }
    }

    // ---------------------------------------------------------------------
    // Reward funding
    // ---------------------------------------------------------------------
    /// @notice Pull `amount` of `token` from the caller and stream it over rewardsDuration.
    ///         Callable by the distributor (USDC leg) or the owner (BNKR staking yield leg).
    function notifyRewardAmount(address token, uint256 amount) external nonReentrant updateReward(address(0)) {
        require(msg.sender == distributor || msg.sender == owner, "not authorized");
        require(isRewardToken(token), "not reward token");
        require(amount > 0, "amount=0");
        uint256 before = IERC20(token).balanceOf(address(this));
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        uint256 received = IERC20(token).balanceOf(address(this)) - before;
        _notifyReward(token, received);
    }

    /// @notice Authorized recovery of idle/forfeited rewards after this token's stream ends.
    function restreamUndistributed(address token) external nonReentrant onlyKeeperOrOwner updateReward(address(0)) {
        require(isRewardToken(token), "not reward token");
        require(block.timestamp >= rewardData[token].periodFinish, "period active");
        uint256 amount = rewardData[token].undistributed;
        require(amount > 0, "nothing to restream");
        rewardData[token].undistributed = 0;
        _notifyReward(token, amount);
        emit UndistributedRestreamed(token, amount);
    }

    function _notifyReward(address token, uint256 reward) internal {
        Reward storage r = rewardData[token];
        uint256 scaled = reward * RATE_PRECISION;
        if (block.timestamp >= r.periodFinish) {
            r.rewardRate = scaled / rewardsDuration;
        } else {
            uint256 leftover = (r.periodFinish - block.timestamp) * r.rewardRate;
            r.rewardRate = (scaled + leftover) / rewardsDuration;
        }

        // Solvency sanity check: the stream for the whole duration must be backed by un-earmarked balance.
        uint256 balance = IERC20(token).balanceOf(address(this));
        uint256 earmarked = r.undistributed + (token == address(usdc) ? buybackReserve : 0);
        uint256 available = balance > earmarked ? balance - earmarked : 0;
        require((r.rewardRate * rewardsDuration) / RATE_PRECISION <= available, "reward > balance");

        r.lastUpdateTime = block.timestamp;
        r.periodFinish = block.timestamp + rewardsDuration;
        emit RewardAdded(token, reward, r.periodFinish);
    }

    function _updateReward(address token, address account) internal {
        Reward storage r = rewardData[token];
        uint256 applicable = lastTimeRewardApplicable(token);
        if (totalSupply == 0) {
            if (applicable > r.lastUpdateTime) {
                r.undistributed += ((applicable - r.lastUpdateTime) * r.rewardRate) / RATE_PRECISION;
            }
        } else {
            r.rewardPerTokenStored = rewardPerToken(token);
        }
        r.lastUpdateTime = applicable;
        if (account != address(0)) {
            rewards[token][account] = earned(token, account);
            userRewardPerTokenPaid[token][account] = r.rewardPerTokenStored;
        }
    }

    // ---------------------------------------------------------------------
    // Buy-and-burn (keeper)
    // ---------------------------------------------------------------------
    /// @notice Spend `usdcAmount` of the buyback reserve on $STAKED via the executor and burn it.
    /// @param minStakedOut Minimum $STAKED the executor must deliver (keeper computes off-chain from a quote).
    function executeBuyback(uint256 usdcAmount, uint256 minStakedOut) external nonReentrant onlyKeeperOrOwner {
        require(address(buybackExecutor) != address(0), "executor unset");
        require(usdcAmount > 0 && usdcAmount <= buybackReserve, "bad amount");
        require(minStakedOut > 0, "minOut=0");

        buybackReserve -= usdcAmount;
        uint256 usdcBefore = usdc.balanceOf(address(this));
        uint256 stakedBefore = stakedToken.balanceOf(address(this));

        usdc.safeApprove(address(buybackExecutor), usdcAmount);
        buybackExecutor.buyback(usdcAmount, minStakedOut);
        usdc.safeApprove(address(buybackExecutor), 0);

        require(usdcBefore - usdc.balanceOf(address(this)) == usdcAmount, "usdc not consumed");
        uint256 delivered = stakedToken.balanceOf(address(this)) - stakedBefore;
        require(delivered >= minStakedOut, "slippage");

        totalBuybackBurned += delivered;
        totalUsdcSpentOnBuyback += usdcAmount;
        stakedToken.safeTransfer(DEAD, delivered);
        emit BuybackExecuted(msg.sender, usdcAmount, delivered);
    }

    // ---------------------------------------------------------------------
    // Admin
    // ---------------------------------------------------------------------
    function setDistributor(address _distributor) external onlyOwner delayedConfiguration {
        distributor = _distributor;
        emit DistributorUpdated(_distributor);
    }

    function setKeeper(address _keeper) external onlyOwner delayedConfiguration {
        keeper = _keeper;
        emit KeeperUpdated(_keeper);
    }

    function setBuybackExecutor(address _executor) external onlyOwner delayedConfiguration {
        buybackExecutor = IBuybackExecutor(_executor);
        emit BuybackExecutorUpdated(_executor);
    }

    /// @dev Only when both streams are finished, so an in-flight stream cannot be shortened or stretched.
    function setRewardsDuration(uint256 _duration) external onlyOwner delayedConfiguration {
        require(_duration >= 1 days && _duration <= 90 days, "bad duration");
        require(
            block.timestamp >= rewardData[address(usdc)].periodFinish
                && block.timestamp >= rewardData[address(bnkr)].periodFinish,
            "period active"
        );
        rewardsDuration = _duration;
        emit RewardsDurationUpdated(_duration);
    }

    /// @notice Recover tokens sent here by mistake. Staking and reward tokens can never be pulled.
    function recoverERC20(address token, uint256 amount, address to) external onlyOwner delayedConfiguration {
        require(token != address(stakedToken) && !isRewardToken(token), "protected");
        IERC20(token).safeTransfer(to, amount);
        emit Recovered(token, amount);
    }

    function _configurationOwner() internal view override returns (address) { return owner; }

    function _isDelayedConfiguration(bytes4 selector) internal pure override returns (bool) {
        return selector == this.setDistributor.selector
            || selector == this.setKeeper.selector
            || selector == this.setBuybackExecutor.selector
            || selector == this.setRewardsDuration.selector
            || selector == this.recoverERC20.selector;
    }
}

contracts/test/AutomationMocks.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
import "../AutomationSupport.sol";
import {IPoolManager} from "../StakedBuybackExecutor.sol";

interface AutomationMint { function mint(address, uint256) external; }
interface AutomationCallback { function unlockCallback(bytes calldata) external returns (bytes memory); }

contract MockDopplerFees {
    address public immutable token0;
    address public immutable token1;
    mapping(address => uint256) public shares;
    uint256 public payout0;
    uint256 public payout1;
    constructor(address a, address b) { token0 = a; token1 = b; }
    function setShares(address beneficiary, uint256 value) external { shares[beneficiary] = value; }
    function setPayout(uint256 a, uint256 b) external { payout0 = a; payout1 = b; }
    function collectFees(bytes32) external returns (uint128, uint128) {
        if (shares[msg.sender] > 0) {
            AutomationMint(token0).mint(msg.sender, payout0);
            AutomationMint(token1).mint(msg.sender, payout1);
            payout0 = 0;
            payout1 = 0;
        }
        // Deliberately unrelated to the beneficiary payout: consumers must use token balances.
        return (1, 2);
    }
    function updateBeneficiary(bytes32, address recipient) external {
        shares[recipient] += shares[msg.sender];
        shares[msg.sender] = 0;
    }
}

contract MockBoundedPoolManager {
    uint256 public mode;
    uint256 public lastLimit;
    bool public lastDirection;
    address private synced;
    uint256 private previousBalance;
    function setMode(uint256 m) external { mode = m; }
    function unlock(bytes calldata data) external returns (bytes memory) {
        if (mode == 2) return "";
        bytes memory result = AutomationCallback(msg.sender).unlockCallback(data);
        if (mode == 3) AutomationCallback(msg.sender).unlockCallback(data);
        return result;
    }
    function swap(IPoolManager.PoolKey memory, IPoolManager.SwapParams memory p, bytes calldata) external returns (int256) {
        lastLimit = p.sqrtPriceLimitX96;
        lastDirection = p.zeroForOne;
        uint256 amount = uint256(-p.amountSpecified);
        if (mode == 1) amount /= 2;
        int128 owed = -int128(int256(amount));
        int128 received = int128(int256(amount * 2));
        if (mode == 4) received = 1;
        (int128 a, int128 b) = p.zeroForOne ? (owed, received) : (received, owed);
        return (int256(a) << 128) | int256(uint256(uint128(b)));
    }
    function sync(address token) external {
        synced = token;
        previousBalance = AutomationToken(token).balanceOf(address(this));
    }
    function settle() external payable returns (uint256) {
        return AutomationToken(synced).balanceOf(address(this)) - previousBalance;
    }
    function take(address token, address recipient, uint256 amount) external {
        AutomationMint(token).mint(recipient, mode == 5 ? amount / 2 : amount);
    }
}

